                do { out = ''; while (out.length < 20) { crypto.getRandomValues(b); if (b[0] < lim) out += pool[b[0] % pool.length]; } } while (!/[a-z]/.test(out) || !/[A-Z]/.test(out) || !/\d/.test(out));
