                color: var(--fm-ink);
                border-color: var(--fm-line-strong);
            }

            .btn-outline-primary i,
            .btn-outline-secondary i {
                color: var(--fm-muted);
            }

            .btn-outline-danger,
            .btn-danger {
                --bs-btn-color: var(--fm-danger);
                --bs-btn-bg: var(--fm-surface);
                --bs-btn-border-color: var(--fm-line-strong);
                --bs-btn-hover-color: var(--fm-danger);
                --bs-btn-hover-bg: var(--fm-danger-soft);
                --bs-btn-hover-border-color: var(--fm-danger);
                --bs-btn-active-color: var(--fm-danger);
                --bs-btn-active-bg: var(--fm-danger-soft);
                --bs-btn-active-border-color: var(--fm-danger);
            }

            .btn-link {
                --bs-btn-color: var(--fm-accent);
                --bs-btn-hover-color: var(--fm-accent-hover);
                --bs-btn-active-color: var(--fm-accent-hover);
            }

            /* a form styled as a button (Download / UnZip on the file page) */
            form.btn {
                padding: 0;
            }

            form.btn > .btn-link {
                padding: 5px 11px !important;
                color: inherit;
                font-size: 13px !important;
                gap: 7px;
            }

            .btn-group > .btn,
            .btn-group > form.btn {
                border-radius: 0;
            }

            .btn-group > .btn:first-child,
            .btn-group > form.btn:first-child {
                border-top-left-radius: 7px;
                border-bottom-left-radius: 7px;
            }

            .btn-group > .btn:last-child,
            .btn-group > form.btn:last-child {
                border-top-right-radius: 7px;
                border-bottom-right-radius: 7px;
            }

            .btn-close:focus {
                box-shadow: var(--fm-focus);
            }

            /* ---- forms ---- */
            .form-control,
            .form-select,
            #inp_copy_to {
                border: 1px solid var(--fm-line-strong);
                border-radius: 7px;
                background-color: var(--fm-surface);
                color: var(--fm-ink);
                font-size: 14px;
            }

            #inp_copy_to {
                padding: 6px 10px;
                min-width: 260px;
            }

            .form-control:focus,
            .form-select:focus,
            #inp_copy_to:focus {
                border-color: var(--fm-accent);
                background-color: var(--fm-surface);
                color: var(--fm-ink);
                box-shadow: var(--fm-focus);
                outline: none;
            }

            .form-control::placeholder {
                color: var(--fm-muted);
            }

            .input-group-text {
                border-color: var(--fm-line-strong);
                background: var(--fm-tier);
                color: var(--fm-muted);
            }

            .form-check-input:checked {
                background-color: var(--fm-accent);
                border-color: var(--fm-accent);
            }

            .form-check-input:focus {
                border-color: var(--fm-accent);
                box-shadow: var(--fm-focus);
            }

            input[type=checkbox],
            input[type=radio] {
                accent-color: var(--fm-accent);
            }

            label,
            .col-form-label {
                color: var(--fm-ink);
                font-weight: 500;
            }

            /* ---- cards, panels, lists ---- */
            .card {
                border: 1px solid var(--fm-line);
                border-radius: 12px;
                background: var(--fm-surface);
                box-shadow: var(--fm-shadow);
                overflow: hidden;
            }

            .card-header {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 12px;
                padding: 14px 20px;
                border-bottom: 1px solid var(--fm-line);
                background: var(--fm-surface);
                color: var(--fm-ink);
                font-size: 15px;
                font-weight: 600;
            }

            .card-header > span > i,
            .card-header > i {
                color: var(--fm-muted);
                margin-right: 4px;
            }

            .card-header a {
                font-size: 13.5px;
                font-weight: 500;
            }

            .card-body {
                padding: 20px;
            }

            .card-header-tabs {
                margin: -14px 0 -15px;
            }

            .nav-tabs {
                gap: 4px;
                border-bottom: 0;
            }

            .nav-tabs .nav-link,
            .nav-tabs .nav-link:visited {
                display: inline-flex;
                align-items: center;
                gap: 7px;
                padding: 15px 4px 13px;
                margin-right: 16px;
                border: 0;
                border-bottom: 2px solid transparent;
                border-radius: 0;
                background: transparent;
                color: var(--fm-muted);
                font-size: 14px;
                font-weight: 500;
            }

            .nav-tabs .nav-link:hover {
                color: var(--fm-ink);
                border-bottom-color: var(--fm-line-strong);
            }

            .nav-tabs .nav-link.active {
                background: transparent;
                color: var(--fm-ink);
                border-bottom-color: var(--fm-accent);
            }

            .list-group {
                border-radius: 12px;
                box-shadow: var(--fm-shadow);
            }

            .list-group .list-group-item,
            .theme-dark .list-group .list-group-item {
                padding: 11px 16px;
                border-color: var(--fm-line);
                background: var(--fm-surface);
                color: var(--fm-ink);
            }

            .list-group-item strong {
                display: inline-block;
                min-width: 120px;
                color: var(--fm-muted);
                font-weight: 500;
            }

            .list-group-item.active,
            .theme-dark .list-group .list-group-item.active {
                background: var(--fm-tier);
                border-color: var(--fm-line);
                color: var(--fm-ink);
                font-size: 15px;
                font-weight: 600;
            }

            .list-group-item.active strong {
                min-width: 0;
                color: var(--fm-muted);
            }

            .list-group-item a {
                display: inline-flex;
                align-items: center;
                gap: 8px;
            }



            /* ---- dropdowns and modals ---- */
            .dropdown-menu {
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                background: var(--fm-surface);
                box-shadow: var(--fm-shadow-lg);
                padding: 6px;
                font-size: 14px;
            }

            .dropdown-item {
                border-radius: 6px;
                color: var(--fm-ink);
            }

            .dropdown-item:hover,
            .dropdown-item:focus {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            .modal-backdrop.show {
                opacity: .45;
            }

            .modal-content {
                border: 1px solid var(--fm-line);
                border-radius: 14px !important;
                background: var(--fm-surface);
                color: var(--fm-ink);
                box-shadow: var(--fm-shadow-lg) !important;
                overflow: hidden;
            }

            .modal-header,
            .modal-footer {
                border-color: var(--fm-line);
                padding: 14px 20px;
            }

            .modal-footer {
                background: var(--fm-tier);
                gap: 8px;
            }

            .modal-footer > * {
                margin: 0;
            }

            .modal-title {
                font-size: 16px;
                font-weight: 600;
            }

            .modal-body {
                padding: 20px;
            }

            .modal-body h5 {
                font-size: 16px;
                font-weight: 600;
                line-height: 1.4;
            }

            .modal-body .form-check-inline {
                margin-right: 20px;
            }

            /* confirm-style dialogs: Cancel / Okay */
            .modal-alert .modal-content {
                max-width: 420px;
                margin: 0 auto;
            }

            .modal-alert .modal-body {
                padding: 28px 24px 20px !important;
            }

            .modal-alert .modal-footer {
                padding: 12px 16px !important;
                justify-content: flex-end;
                flex-wrap: nowrap;
            }

            .modal-alert .modal-footer .btn {
                flex: 0 0 auto;
                width: auto;
                min-width: 96px;
                height: 36px;
                padding: 0 16px;
                border: 1px solid var(--fm-line-strong) !important;
                border-radius: 7px !important;
                background: var(--fm-surface);
                color: var(--fm-ink);
                font-size: 14px !important;
            }

            .modal-alert .modal-footer .btn:hover {
                background: var(--fm-hover);
            }

            .modal-alert .modal-footer .btn[type=submit],
            .modal-alert .modal-footer #bulk-confirm-ok {
                border-color: var(--fm-accent) !important;
                background: var(--fm-accent);
                color: var(--fm-accent-ink);
            }

            .modal-alert .modal-footer .btn[type=submit]:hover,
            .modal-alert .modal-footer #bulk-confirm-ok:hover {
                background: var(--fm-accent-hover);
            }

            .modal-alert .modal-footer .btn strong {
                font-weight: 500;
            }

            #bulk-confirm-list .list-group-item {
                padding: 7px 12px;
                font-size: 13px;
            }

            #bulk-confirm-list {
                box-shadow: none;
            }



            /* advanced search results */
            ul#search-wrapper {
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                overflow: hidden;
            }

            ul#search-wrapper li {
                padding: 8px 12px;
                border-bottom: 1px solid var(--fm-line);
            }

            ul#search-wrapper li:last-child {
                border-bottom: 0;
            }


            .lds-facebook div {
                background: var(--fm-accent);
            }

            /* ---- messages and toast ---- */
            .message {
                display: flex;
                align-items: center;
                gap: 10px;
                margin: 0 0 16px;
                padding: 11px 14px;
                border: 1px solid var(--fm-line);
                border-left-width: 3px;
                border-radius: 10px;
                background: var(--fm-surface);
                color: var(--fm-ink);
                box-shadow: var(--fm-shadow);
            }

            .message::before {
                font: normal normal normal 15px/1 FontAwesome;
                content: "\f05a";
                color: var(--fm-accent);
            }

            .message.ok {
                border-color: var(--fm-success);
                background: var(--fm-success-soft);
                color: var(--fm-ink);
            }

            .message.ok::before {
                content: "\f058";
                color: var(--fm-success);
            }

            .message.error {
                border-color: var(--fm-danger);
                background: var(--fm-danger-soft);
                color: var(--fm-ink);
            }

            .message.error::before {
                content: "\f06a";
                color: var(--fm-danger);
            }

            .message.alert {
                border-color: var(--fm-warning);
                background: var(--fm-warning-soft);
                color: var(--fm-ink);
            }

            .message.alert::before {
                content: "\f071";
                color: var(--fm-warning);
            }

            #snackbar {
                display: flex;
                align-items: center;
                gap: 10px;
                min-width: 240px;
                max-width: min(460px, calc(100vw - 32px));
                padding: 12px 18px !important;
                border-radius: 10px !important;
                background: var(--fm-ink) !important;
                color: var(--fm-surface) !important;
                font-size: 14px;
                text-align: left !important;
                transform: translateX(-50%);
                margin-left: 0 !important;
                z-index: 2000 !important;
                box-shadow: var(--fm-shadow-lg);
            }

            #snackbar i {
                flex: 0 0 auto;
                color: #4ADE80;
                font-size: 16px;
            }

            #snackbar.show.is-error {
                -webkit-animation: fadein .5s, fadeout .5s 5.5s;
                animation: fadein .5s, fadeout .5s 5.5s;
            }

            #snackbar.is-error {
                background: var(--fm-danger-solid) !important;
                color: #FFFFFF !important;
            }

            #snackbar.is-error i {
                color: #FFFFFF;
            }

            ul#search-wrapper > p.is-error:only-child {
                color: var(--fm-danger);
            }

            ul#search-wrapper > p.is-error:only-child::before {
                content: "\f071";
                color: var(--fm-danger);
            }

            /* ---- file list ---- */
            .table-responsive:has(#main-table) {
                overflow: hidden;
                border: 1px solid var(--fm-line);
                border-radius: 12px;
                background: var(--fm-surface);
                box-shadow: var(--fm-shadow);
            }

            #main-table {
                --bs-table-bg: transparent;
                --bs-table-hover-bg: var(--fm-hover);
                --bs-table-hover-color: var(--fm-ink);
                --bs-table-color: var(--fm-ink);
                margin: 0;
                color: var(--fm-ink);
                font-size: 14px;
            }

            #main-table.table-bordered > :not(caption) > * > *,
            .theme-dark #main-table.table-bordered td,
            .theme-dark #main-table.table-bordered th {
                border-width: 0 0 1px;
                border-color: var(--fm-line);
            }

            #main-table > :not(caption) > * > * {
                padding: 4px 12px;
                vertical-align: middle;
                background-color: transparent;
                box-shadow: none;
            }

            #main-table thead th {
                padding-top: 11px;
                padding-bottom: 11px;
                background: var(--fm-tier);
                color: var(--fm-muted);
                font-size: 12.5px;
                font-weight: 600;
                letter-spacing: .01em;
            }

            #main-table thead th:last-child {
                text-align: right;
                padding-right: 16px;
            }

            #main-table tbody tr {
                transition: background-color .12s;
            }

            #main-table tbody tr:hover,
            #main-table tr.even:hover {
                background: var(--fm-hover);
            }

            #main-table tr.even,
            .table-hover > tbody > tr:hover > td:first-child {
                background-color: transparent;
                border-left: 0;
            }

            #main-table tbody tr:has(input[name="file[]"]:checked) {
                background: var(--fm-accent-soft);
            }

            #main-table .custom-checkbox-td,
            #main-table .custom-checkbox-header {
                width: 44px !important;
                padding-left: 16px;
            }

            #main-table input[type=checkbox] {
                width: 15px;
                height: 15px;
                cursor: pointer;
                vertical-align: middle;
            }

            #main-table .filename a,
            .theme-dark #main-table .filename a {
                display: inline-flex;
                align-items: center;
                gap: 10px;
                max-width: 100%;
                min-height: 26px;
                vertical-align: middle;
                color: var(--fm-ink);
                font-weight: 500;
            }

            #main-table .filename a:hover {
                color: var(--fm-accent);
            }

            #main-table .filename > a > i,
            #main-table .filename i[class^="fa"] {
                width: 18px;
                margin: 0;
                font-size: 16px;
                text-align: center;
            }

            #main-table i.fa.fa-folder-o,
            .theme-dark #main-table i.fa.fa-folder-o {
                color: var(--fm-folder);
            }

            #main-table i.fa.fa-file-o {
                color: var(--fm-muted);
            }

            #main-table .filename > i {
                color: var(--fm-muted);
                font-size: 13px;
            }

            #main-table td:nth-child(n+3) {
                color: var(--fm-muted);
                font-variant-numeric: tabular-nums;
            }

            #main-table td a[title="Change Permissions"],
            #main-table td a[title="Change Permissions"]:visited {
                padding: 2px 6px;
                border-radius: 5px;
                background: var(--fm-tier);
                border: 1px solid var(--fm-line);
                color: var(--fm-muted);
                font-family: var(--fm-mono);
                font-size: 12.5px;
            }

            #main-table td a[title="Change Permissions"]:hover {
                border-color: var(--fm-accent);
                color: var(--fm-accent);
            }

            #main-table .fm-parent-link,
            #main-table .fm-parent-link:visited {
                display: inline-flex;
                align-items: center;
                gap: 10px;
                color: var(--fm-muted);
                font-weight: 500;
            }

            #main-table .fm-parent-link i {
                width: 18px;
                text-align: center;
                font-size: 15px;
            }

            #main-table .fm-parent-link:hover {
                color: var(--fm-accent);
            }

            /* row actions: quiet icon buttons */
            #main-table td.inline-actions {
                padding-right: 12px;
                text-align: right;
                white-space: nowrap;
            }

            #main-table .inline-actions > a,
            #main-table .inline-actions > a:visited {
                display: inline-grid;
                place-items: center;
                width: 26px;
                height: 26px;
                border-radius: 6px;
                color: var(--fm-muted);
                transition: background-color .12s, color .12s;
            }

            #main-table .inline-actions > a > i,
            .theme-dark #main-table .inline-actions > a > i {
                margin: 0;
                padding: 0;
                background: none;
                color: inherit;
                font-size: 15px;
            }

            #main-table .inline-actions > a:hover {
                background: var(--fm-surface);
                box-shadow: inset 0 0 0 1px var(--fm-line-strong);
            }

            #main-table .inline-actions > a.is-danger:hover {
                background: var(--fm-danger-soft);
                color: var(--fm-danger);
                box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--fm-danger) 35%, transparent);
            }


            /* ---- list grid: type badges, aligned columns ---- */
            .fm-ficon {
                position: relative;
                display: inline-grid;
                flex: 0 0 auto;
                place-items: end center;
                width: 22px;
                height: 26px;
                padding-bottom: 3px;
                border-radius: 3px 6px 3px 3px;
                background: var(--fi, #8792A8);
                color: var(--fi-ink, #FFFFFF);
                clip-path: polygon(0 0, 68% 0, 100% 26%, 100% 100%, 0 100%);
                font: 800 7px/1 var(--bs-body-font-family);
                letter-spacing: .02em;
            }

            .fm-ficon::after {
                content: "";
                position: absolute;
                top: 0;
                right: 0;
                width: 32%;
                height: 26%;
                background: linear-gradient(to bottom left, transparent 50%, rgba(255, 255, 255, .5) 50%);
            }

            .fm-ficon.is-long {
                font-size: 6px;
                letter-spacing: 0;
            }

            .fm-ficon.is-plain {
                background: var(--fm-line-strong);
            }

            .fm-ficon.is-folder {
                place-items: center;
                width: 22px;
                padding: 0;
                background: none;
                clip-path: none;
            }

            .fm-ficon.is-folder::after {
                content: none;
            }

            #main-table .fm-ficon.is-folder i.fa {
                width: auto;
                color: var(--fm-folder);
                font-size: 17px;
            }

            .fm-ficon.is-folder.is-link::after {
                content: "\f0c1";
                top: auto;
                right: -3px;
                bottom: 0;
                width: auto;
                height: auto;
                padding: 1px;
                border-radius: 3px;
                background: var(--fm-surface);
                color: var(--fm-muted);
                font: normal 8px/1 FontAwesome;
            }

            .fm-ficon.is-folder i.fa {
                width: auto;
                margin: 0;
                color: var(--fm-folder);
                font-size: 17px;
            }

            .fm-ficon.is-lg {
                width: 30px;
                height: 36px;
                padding-bottom: 5px;
                border-radius: 4px 8px 4px 4px;
                font-size: 9.5px;
            }

            .fm-ficon.is-lg.is-long {
                font-size: 8px;
            }

            .fm-ficon.is-lg.is-folder {
                width: 30px;
            }

            .fm-ficon.is-lg.is-folder i.fa {
                font-size: 26px;
            }

            .fm-crumbs .dropdown-item {
                display: flex;
                align-items: center;
                gap: 10px;
            }

            .fm-crumb-file .fm-ficon {
                margin-right: 6px;
            }

            #bulk-confirm-list .list-group-item {
                display: flex;
                align-items: center;
                gap: 10px;
            }

            #bulk-confirm-list .list-group-item > span:last-child,
            .fm-copy-items li > span:last-child {
                min-width: 0;
                overflow-wrap: anywhere;
            }

            #main-table .fm-fname {
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            #main-table .fm-link-target {
                margin-left: 8px;
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            #main-table th.fm-col-size,
            #main-table td.fm-col-size {
                padding-right: 28px;
                text-align: right;
                white-space: nowrap;
            }

            #main-table td.fm-col-date {
                white-space: nowrap;
            }

            #main-table .fm-size-none {
                color: var(--fm-line-strong);
            }

            /* sort arrows drawn with the icon font instead of images */
            table.dataTable thead .sorting,
            table.dataTable thead .sorting_asc,
            table.dataTable thead .sorting_desc {
                background-image: none !important;
                cursor: pointer;
            }

            table.dataTable thead .sorting::after,
            table.dataTable thead .sorting_asc::after,
            table.dataTable thead .sorting_desc::after {
                font: normal normal normal 11px/1 FontAwesome;
                content: "\f0dc";
                margin-left: 6px;
                opacity: .45;
            }

            table.dataTable thead .sorting_asc::after {
                content: "\f0de";
                opacity: 1;
                color: var(--fm-accent);
            }

            table.dataTable thead .sorting_desc::after {
                content: "\f0dd";
                opacity: 1;
                color: var(--fm-accent);
            }

            table.dataTable thead .sorting_asc,
            table.dataTable thead .sorting_desc {
                color: var(--fm-ink) !important;
            }

            /* summary and empty state */
            #main-table tfoot td {
                padding: 0 !important;
                border-bottom: 0 !important;
            }

            .fm-summary {
                display: flex;
                flex-wrap: wrap;
                gap: 8px 24px;
                padding: 12px 16px;
                background: var(--fm-tier);
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-summary > span {
                display: inline-flex;
                align-items: center;
                gap: 7px;
            }

            .fm-summary strong {
                color: var(--fm-ink);
                font-weight: 600;
                font-variant-numeric: tabular-nums;
            }

            .fm-empty {
                display: flex;
                flex-direction: column;
                align-items: center;
                gap: 6px;
                padding: 48px 16px;
                color: var(--fm-muted);
                text-align: center;
            }

            .fm-empty i {
                font-size: 34px;
                color: var(--fm-line-strong);
                margin-bottom: 6px;
            }

            .fm-empty strong {
                color: var(--fm-ink);
                font-size: 15px;
                font-weight: 600;
            }

            /* ---- upload ---- */
            form.dropzone,
            .theme-dark form.dropzone {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                justify-content: center;
                min-height: 240px;
                margin-top: 12px;
                border: 2px dashed var(--fm-line-strong);
                border-radius: 12px;
                background: var(--fm-tier);
                color: var(--fm-muted);
                line-height: 1.5;
                transition: border-color .15s, background-color .15s;
            }

            form.dropzone .dz-message {
                display: flex;
                flex-direction: column;
                align-items: center;
                gap: 6px;
                margin: 0;
                font-size: 15px;
                font-weight: 500;
            }

            form.dropzone .dz-message::before {
                font: normal normal normal 34px/1 FontAwesome;
                content: "\f0ee";
                color: var(--fm-accent);
                margin-bottom: 6px;
            }

            form.dropzone:hover,
            form.dropzone.dz-drag-hover {
                border-color: var(--fm-accent);
                background: var(--fm-accent-soft);
            }

            .fm-upload-wrapper .card-text {
                color: var(--fm-muted);
            }

            .fm-upload-wrapper .card-text strong {
                color: var(--fm-ink);
                font-weight: 600;
            }

            /* ---- editor and preview ---- */
            #normal-editor {
                width: 100%;
                border: 1px solid var(--fm-line-strong);
                border-radius: 12px;
                background: var(--fm-surface);
                color: var(--fm-ink);
                font-family: var(--fm-mono);
                font-size: 13px;
                line-height: 1.6;
                padding: 16px;
            }

            #normal-editor:focus {
                border-color: var(--fm-accent);
                box-shadow: var(--fm-focus);
            }


            .edit-file-actions .btn-group,
            .js-ace-toolbar {
                box-shadow: var(--fm-shadow);
                border-radius: 7px;
            }

            .js-ace-toolbar select {
                border: 1px solid var(--fm-line-strong);
                background-color: var(--fm-surface);
                color: var(--fm-ink);
                font-size: 13px;
                padding: 0 6px;
            }

            pre.with-hljs {
                border: 1px solid var(--fm-line);
                border-radius: 12px;
                box-shadow: var(--fm-shadow);
            }

            pre.with-hljs code {
                padding: 16px !important;
                font-family: var(--fm-mono);
                font-size: 13px;
            }

            .preview-img {
                border-radius: 10px;
                border: 1px solid var(--fm-line);
            }

            /* ---- settings, help, copy, chmod ---- */
            .card .table {
                --bs-table-bg: transparent;
                color: var(--fm-ink);
            }


            .card p .btn + .btn,
            .card p b + .btn {
                margin-left: 6px;
            }

            .card .list-group-flush {
                box-shadow: none;
                border-radius: 10px;
            }

            .card .list-group-flush .list-group-item {
                border: 1px solid var(--fm-line);
                border-radius: 10px;
            }

            /* ---- login ---- */
            body.fm-login-page,
            body.fm-login-page.theme-dark {
                background: var(--fm-bg);
            }

            .row > pre.with-hljs {
                flex: 0 0 auto;
                width: calc(100% - var(--bs-gutter-x));
                margin-left: calc(var(--bs-gutter-x) * .5);
                margin-right: calc(var(--bs-gutter-x) * .5);
                padding: 0;
            }

            .card-header h6 {
                margin: 0;
                font-size: 15px;
                font-weight: 600;
            }




            .fm-hint {
                color: var(--fm-muted);
                margin-bottom: 10px;
            }

            .fm-folder-picker {
                margin: 0 0 20px;
                padding: 0;
                list-style: none;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                max-height: 360px;
                overflow-y: auto;
            }

            .fm-folder-picker li + li {
                border-top: 1px solid var(--fm-line);
            }

            .fm-folder-picker a,
            .fm-folder-picker a:visited {
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 9px 14px;
                color: var(--fm-ink);
                font-weight: 500;
            }

            .fm-folder-picker a:hover {
                background: var(--fm-hover);
                color: var(--fm-accent);
            }

            .fm-folder-picker i.fa-folder-o {
                color: var(--fm-folder);
            }

            .fm-folder-picker i.fa-level-up {
                flex: 0 0 22px;
                color: var(--fm-muted);
                text-align: center;
            }

            .fm-card-actions {
                display: flex;
                justify-content: flex-end;
                gap: 8px;
            }

            .fm-login-page .card-wrapper {
                width: 380px;
            }

            .fm-login-page .card.fat {
                border: 1px solid var(--fm-line);
                border-radius: 16px;
                box-shadow: var(--fm-shadow-lg);
            }

            .fm-login-page .card-body {
                padding: 32px;
            }

            .fm-login-brand {
                display: flex;
                flex-direction: column;
                align-items: center;
                gap: 6px;
                margin-bottom: 28px;
                text-align: center;
            }

            .fm-login-logo {
                width: 230px;
                max-width: 100%;
                height: auto;
                margin-bottom: 14px;
            }

            .fm-login-brand h1 {
                margin: 0;
                font-size: 20px;
                font-weight: 600;
                letter-spacing: -.01em;
            }

            .fm-login-brand p {
                margin: 0;
                color: var(--fm-muted);
            }

            .fm-login-page label {
                padding-bottom: 6px !important;
            }

            .fm-login-page .form-control,
            .theme-dark.fm-login-page .form-control {
                height: 42px;
                border-width: 1px;
                background: var(--fm-surface);
                color: var(--fm-ink);
            }

            .fm-login-page .btn.btn-block {
                height: 44px;
                margin-top: 8px !important;
                font-size: 15px;
            }

            .fm-login-page .message {
                margin: 0;
            }

            .fm-login-server {
                margin-top: 4px;
                padding-top: 16px;
                border-top: 1px solid var(--fm-line);
                text-align: center;
                font-weight: 600;
                color: var(--fm-muted);
            }

            .fm-login-server i {
                margin-right: 4px;
            }

            .fm-login-server strong {
                margin-left: 4px;
                font-family: var(--fm-mono);
                font-weight: 700;
                color: var(--fm-ink);
            }

            /* ---- coloured band dialogs: delete (red), zip (orange), tar (violet) ---- */
            .modal-danger {
                --fm-band: var(--fm-danger-solid);
                --fm-band-hover: var(--fm-danger-solid-hover);
                --fm-band-soft: var(--fm-danger-soft);
                --fm-band-text: var(--fm-danger);
            }

            .modal-zip {
                --fm-band: var(--fm-zip-solid);
                --fm-band-hover: var(--fm-zip-solid-hover);
                --fm-band-soft: var(--fm-zip-soft);
                --fm-band-text: var(--fm-zip-text);
                --fm-band-ink: var(--fm-zip-ink);
            }

            .modal-tar {
                --fm-band: var(--fm-tar-solid);
                --fm-band-hover: var(--fm-tar-solid-hover);
                --fm-band-soft: var(--fm-tar-soft);
                --fm-band-text: var(--fm-ic-tar);
            }

            .modal-download {
                --fm-band: var(--fm-dl-solid);
                --fm-band-hover: var(--fm-dl-solid-hover);
                --fm-band-soft: var(--fm-success-soft);
                --fm-band-text: var(--fm-success);
            }

            .fm-name-meta {
                margin-left: auto;
                padding-left: 12px;
                color: var(--fm-muted);
                font-weight: 500;
                white-space: nowrap;
            }

            .fm-choice {
                display: grid;
                gap: 8px;
            }

            .fm-choice-item {
                display: flex;
                align-items: center;
                gap: 12px;
                margin: 0;
                padding: 11px 14px;
                border: 1px solid var(--fm-line-strong);
                border-radius: 10px;
                cursor: pointer;
                transition: border-color .15s, background-color .15s;
            }

            .fm-choice-item:hover {
                background: var(--fm-hover);
            }

            .fm-choice-item:has(input:checked) {
                border-color: var(--fm-band, var(--fm-accent));
                background: var(--fm-band-soft, var(--fm-accent-soft));
            }

            .fm-choice-item input {
                flex: 0 0 auto;
                width: 16px;
                height: 16px;
                margin: 0;
                accent-color: var(--fm-band, var(--fm-accent));
            }

            .fm-choice-item > i {
                width: 18px;
                color: var(--fm-folder);
                font-size: 16px;
                text-align: center;
            }

            .fm-choice-item span {
                display: flex;
                flex-direction: column;
                min-width: 0;
                font-weight: 500;
            }

            .fm-choice-item small {
                color: var(--fm-muted);
                font-weight: 400;
                word-break: break-all;
            }

            #extractModal .modal-content {
                max-width: 480px;
            }

            .modal-band .modal-content {
                border-color: color-mix(in srgb, var(--fm-band) 45%, var(--fm-line));
            }

            .fm-modal-band {
                display: none;
            }

            .modal-band .fm-modal-band {
                display: flex;
                align-items: center;
                gap: 14px;
                padding: 18px 22px;
                background: var(--fm-band);
                color: var(--fm-band-ink, #FFFFFF);
            }

            .modal-band .fm-modal-band h5 {
                margin: 0;
                color: var(--fm-band-ink, #FFFFFF);
                font-size: 17px;
                font-weight: 600;
            }

            .fm-band-icon {
                display: grid;
                place-items: center;
                flex: 0 0 40px;
                width: 40px;
                height: 40px;
                border-radius: 50%;
                background: rgba(255, 255, 255, .18);
                box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .35);
                font-size: 18px;
            }

            .modal-band .modal-body {
                padding: 20px 22px !important;
                text-align: left !important;
            }

            .modal-band #bulk-confirm-title {
                display: none;
            }

            .fm-danger-name {
                display: flex;
                align-items: center;
                gap: 10px;
                margin: 0 0 14px;
                padding: 10px 12px;
                border: 1px solid var(--fm-line);
                border-radius: 8px;
                background: var(--fm-tier);
                font-weight: 600;
                word-break: break-all;
            }

            .fm-danger-name i.fa {
                color: var(--fm-muted);
            }

            .fm-band-icon i.fa {
                color: var(--fm-band-ink, #FFFFFF);
            }

            .modal-zip .fm-band-icon {
                background: rgba(66, 32, 6, .10);
                box-shadow: inset 0 0 0 1px rgba(66, 32, 6, .25);
            }

            .fm-danger-alert {
                display: none;
            }

            .modal-band .fm-danger-alert {
                display: flex;
                align-items: flex-start;
                gap: 10px;
                margin-top: 14px;
                padding: 11px 13px;
                border: 1px solid color-mix(in srgb, var(--fm-band-text) 35%, transparent);
                border-radius: 8px;
                background: var(--fm-band-soft);
                color: var(--fm-ink);
                font-size: 13.5px;
                text-align: left;
            }

            .modal-band .fm-danger-alert i {
                margin-top: 2px;
                color: var(--fm-band-text);
            }

            .modal-band .fm-danger-alert strong {
                color: var(--fm-band-text);
            }

            .modal-band .fm-danger-name + .fm-danger-alert {
                margin-top: 0;
            }

            .modal-band #bulk-confirm-desc {
                margin-bottom: 4px !important;
                font-weight: 500;
            }

            .modal-band #bulk-confirm-count {
                margin-bottom: 10px !important;
            }

            .modal-alert.modal-band .modal-footer .btn[type=submit],
            .modal-alert.modal-band .modal-footer #bulk-confirm-ok,
            .fm-btn-delete {
                border-color: var(--fm-band, var(--fm-danger-solid)) !important;
                background: var(--fm-band, var(--fm-danger-solid));
                color: var(--fm-band-ink, #FFFFFF);
            }

            .modal-alert.modal-band .modal-footer .btn[type=submit]:hover,
            .modal-alert.modal-band .modal-footer #bulk-confirm-ok:hover,
            .fm-btn-delete:hover {
                background: var(--fm-band-hover, var(--fm-danger-solid-hover));
                color: var(--fm-band-ink, #FFFFFF);
            }

            .modal-band .modal-footer .btn i {
                color: inherit !important;
            }

            /* ---- rename ---- */
            .fm-rename-title i {
                color: var(--fm-ic-edit);
                margin-right: 4px;
            }

            .fm-rename-current i.fa-folder-o {
                color: var(--fm-folder);
            }

            .fm-rename-input {
                height: 42px;
                font-weight: 500;
            }

            .fm-rename-hint {
                min-height: 20px;
                margin-top: 6px;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-rename-hint.is-problem {
                color: var(--fm-danger);
            }

            #renameDialog .modal-dialog {
                max-width: 460px;
            }

            #js-rename-submit:disabled {
                opacity: .5;
            }


            .fm-search-field {
                position: relative;
                display: flex;
                align-items: center;
                flex: 1;
                height: 44px;
                padding: 0 5px 0 40px;
                border: 1px solid var(--fm-line-strong);
                border-radius: 10px;
                background: var(--fm-surface);
                transition: border-color .15s, box-shadow .15s;
            }

            .fm-search-field:focus-within {
                border-color: var(--fm-accent);
                box-shadow: var(--fm-focus);
            }

            .fm-search-field > i {
                position: absolute;
                left: 15px;
                color: var(--fm-muted);
                pointer-events: none;
            }

            .fm-search-field input {
                flex: 1;
                min-width: 0;
                height: 100%;
                border: 0;
                background: transparent;
                color: var(--fm-ink);
                font-size: 15px;
                outline: none;
                box-shadow: none !important;
            }

            .fm-search-field input::placeholder {
                color: var(--fm-muted);
            }

            .fm-search-field input::-webkit-search-cancel-button {
                cursor: pointer;
            }

            .fm-search-field .btn {
                height: 34px;
                padding: 0 16px;
                border-radius: 7px;
                font-size: 13.5px;
            }

            ul#search-wrapper:has(> p:only-child) {
                border: 0;
            }

            ul#search-wrapper > p:only-child {
                display: flex;
                flex-direction: column;
                align-items: center;
                gap: 8px;
                margin: 0 !important;
                padding: 28px 12px;
                color: var(--fm-muted);
                text-align: center;
            }

            ul#search-wrapper > p:only-child::before {
                font: normal normal normal 26px/1 FontAwesome;
                content: "\f002";
                color: var(--fm-line-strong);
            }

            /* ---- advanced search results ---- */
            ul#search-wrapper li a {
                display: flex;
                align-items: center;
                gap: 10px;
                color: var(--fm-ink);
            }

            ul#search-wrapper li a > span {
                display: flex;
                flex-direction: column;
                min-width: 0;
            }

            ul#search-wrapper li a strong {
                font-weight: 600;
            }

            ul#search-wrapper li a small {
                color: var(--fm-muted);
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            ul#search-wrapper li a:hover strong {
                color: var(--fm-accent);
            }


            .fm-search-scope {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 8px 12px;
                margin-bottom: 14px;
            }

            .fm-search-scope .fm-copy-label {
                margin: 0;
            }

            .fm-search-scope .fm-segmented label {
                max-width: 340px;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-search-scope .fm-segmented input:checked + label i.fa-folder-open-o {
                color: var(--fm-folder);
            }

            .fm-search-scope .fm-segmented input:checked + label i.fa-server {
                color: var(--fm-ic-archive);
            }

            .fm-search-where {
                flex-basis: 100%;
                display: flex;
                align-items: center;
                gap: 8px;
                margin: 0;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-search-where span {
                min-width: 0;
                overflow-wrap: anywhere;
            }

            .fm-search-where i {
                color: var(--fm-folder);
            }

            .fm-search-scope.is-all .fm-search-where i {
                color: var(--fm-ic-archive);
            }

            .fm-search-where strong {
                color: var(--fm-ink);
                font-weight: 600;
            }

            ul#search-wrapper li.fm-search-busy {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 12px;
                padding: 14px 16px;
                background: var(--fm-surface);
                color: var(--fm-muted);
            }

            ul#search-wrapper li.fm-search-busy strong {
                color: var(--fm-ink);
            }

            ul#search-wrapper li.fm-search-busy i.fa-spin {
                color: var(--fm-accent);
                margin-right: 6px;
            }

            ul#search-wrapper li.fm-search-partial {
                display: flex;
                align-items: flex-start;
                gap: 8px;
                background: var(--fm-warning-soft);
                color: var(--fm-ink);
                font-size: 13px;
            }

            ul#search-wrapper li.fm-search-partial i {
                margin-top: 2px;
                color: var(--fm-warning);
            }

            .lds-facebook.show-me {
                display: none;
            }

            /* ---- copy / move modal ---- */
            #copyModal .modal-title i {
                color: var(--fm-ic-copy);
                margin-right: 4px;
            }

            .fm-copy-grid {
                display: grid;
                grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
                gap: 24px;
            }

            .fm-copy-label {
                display: flex;
                align-items: center;
                gap: 8px;
                margin: 0 0 8px;
                color: var(--fm-muted);
                font-size: 13px;
                font-weight: 600;
            }

            .fm-copy-items + .fm-copy-label {
                margin-top: 20px;
            }

            .fm-copy-count {
                padding: 1px 8px;
                border-radius: 999px;
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-size: 12px;
            }

            .fm-copy-items {
                max-height: 180px;
                margin: 0;
                padding: 0;
                overflow-y: auto;
                list-style: none;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
            }

            .fm-copy-items li {
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 8px 12px;
                font-weight: 500;
                word-break: break-all;
            }

            .fm-copy-items li + li {
                border-top: 1px solid var(--fm-line);
            }

            .fm-copy-items li i {
                color: var(--fm-muted);
            }

            .fm-segmented {
                display: inline-flex;
                padding: 3px;
                border: 1px solid var(--fm-line);
                border-radius: 9px;
                background: var(--fm-tier);
            }

            .fm-segmented input {
                position: absolute;
                opacity: 0;
                pointer-events: none;
            }

            .fm-segmented label {
                display: inline-flex;
                align-items: center;
                gap: 7px;
                padding: 6px 16px;
                border-radius: 6px;
                color: var(--fm-muted);
                font-size: 13.5px;
                cursor: pointer;
                transition: background-color .15s, color .15s;
            }

            .fm-segmented input:checked + label {
                background: var(--fm-surface);
                color: var(--fm-ink);
                box-shadow: var(--fm-shadow);
            }

            .fm-segmented input:checked + label i.fa-files-o {
                color: var(--fm-ic-copy);
            }

            .fm-segmented input:checked + label i.fa-arrow-right {
                color: var(--fm-ic-archive);
            }

            [data-bs-theme=dark] .fm-segmented input:checked + label,
            [data-bs-theme=dark] .fm-segmented .nav-link.active {
                background: var(--fm-hover);
                box-shadow: inset 0 0 0 1px var(--fm-line-strong);
            }

            .fm-segmented input:focus-visible + label {
                box-shadow: var(--fm-focus);
            }

            .fm-copy-mode-hint {
                margin: 8px 0 0;
                font-size: 13px;
            }

            .fm-dest-crumbs {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 2px;
                margin-bottom: 8px;
                padding: 4px;
                border: 1px solid var(--fm-line);
                border-radius: 9px;
                background: var(--fm-tier);
            }

            .fm-dest-crumbs .fm-crumb {
                display: inline-flex;
                align-items: center;
                padding: 3px 8px;
                border-radius: 6px;
                color: var(--fm-muted);
                font-size: 13.5px;
            }

            .fm-dest-crumbs .fm-crumb:hover {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            .fm-dest-crumbs .fm-crumb.is-current {
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-weight: 600;
            }

            .fm-dest-crumbs .fm-crumb-sep {
                color: var(--fm-muted);
                opacity: .6;
            }

            .fm-dest-list {
                height: 240px;
                max-height: none;
                margin-bottom: 10px;
            }

            .fm-dest-list a .fm-dest-go {
                margin-left: auto;
                color: var(--fm-muted);
                opacity: 0;
                transition: opacity .12s;
            }

            .fm-dest-list a:hover .fm-dest-go {
                opacity: 1;
            }

            .fm-dest-list .fm-dest-up,
            .fm-dest-list .fm-dest-up:visited {
                color: var(--fm-muted);
            }

            .fm-dest-state {
                padding: 14px;
                color: var(--fm-muted);
                font-size: 13.5px;
            }

            .fm-dest-state.is-error {
                color: var(--fm-danger);
            }

            .fm-dest-note {
                display: flex;
                align-items: flex-start;
                gap: 8px;
                padding: 9px 12px;
                border-radius: 8px;
                background: var(--fm-success-soft);
                color: var(--fm-ink);
                font-size: 13px;
                word-break: break-all;
            }

            .fm-dest-note i {
                margin-top: 2px;
                color: var(--fm-success);
            }

            .fm-dest-note.is-problem {
                background: var(--fm-warning-soft);
            }

            .fm-dest-note.is-problem i {
                color: var(--fm-warning);
            }

            .fm-copy-mode-hint + .fm-conflict-label {
                margin-top: 18px;
            }

            .fm-conflict-seg label {
                padding: 6px 11px;
            }

            .fm-conflict-seg input:checked + label i.fa-step-forward {
                color: var(--fm-muted);
            }

            .fm-conflict-seg input:checked + label i.fa-refresh {
                color: var(--fm-warning);
            }

            .fm-conflict-seg input:checked + label i.fa-clone {
                color: var(--fm-ic-copy);
            }

            .fm-copy-exists-count {
                padding: 1px 8px;
                border-radius: 999px;
                background: var(--fm-warning-soft);
                color: var(--fm-warning);
                font-size: 12px;
            }

            .fm-copy-items li.is-conflict {
                background: var(--fm-warning-soft);
            }

            .fm-copy-items li.is-kept {
                background: var(--fm-tier);
            }

            .fm-copy-items li.is-kept .fm-copy-exists {
                color: var(--fm-muted);
            }

            .fm-copy-items li .fm-copy-each {
                width: 118px;
                padding: 2px 28px 2px 9px;
                border-color: var(--fm-line-strong);
                background-color: var(--fm-surface);
                color: var(--fm-ink);
                font-size: 12.5px;
                font-weight: 500;
                background-position: right 8px center;
            }

            .fm-copy-items li .fm-copy-exists {
                flex: none;
                margin-left: auto;
                color: var(--fm-warning);
                font-size: 12px;
                font-weight: 600;
                white-space: nowrap;
                word-break: normal;
            }

            #js-copy-submit {
                min-width: 130px;
            }

            #js-copy-submit:disabled {
                opacity: .5;
            }

            @media (max-width: 767.98px) {
                .fm-copy-grid {
                    grid-template-columns: 1fr;
                    gap: 16px;
                }

                .fm-dest-list {
                    height: 200px;
                }
            }

            /* ---- shared page layout (upload, settings, help) ---- */
            /* one width for every page (Settings, Environment, Change password, Help, Upload, …); the file view is full width */
            .fm-page {
                max-width: 1280px;
                margin: 8px auto 40px;
            }

            .fm-page-head {
                display: flex;
                flex-wrap: wrap;
                align-items: flex-end;
                justify-content: space-between;
                gap: 16px;
                margin-bottom: 18px;
            }

            .fm-page-head h1 {
                margin: 0 0 4px;
                font-size: 22px;
                font-weight: 650;
                letter-spacing: -.01em;
            }

            .fm-page-head p {
                margin: 0;
                color: var(--fm-muted);
            }

            .fm-path-chip {
                display: inline-flex;
                align-items: center;
                gap: 7px;
                padding: 2px 9px;
                border: 1px solid var(--fm-line);
                border-radius: 7px;
                background: var(--fm-surface);
                color: var(--fm-ink);
                font-family: var(--fm-mono);
                font-size: 13px;
                word-break: break-all;
            }

            .fm-path-chip i {
                color: var(--fm-folder);
            }

            /* ---- file pages: summary in the top bar, details in a slide-over panel ---- */
            .fm-bar-file {
                display: flex;
                align-items: center;
                gap: 10px;
                min-width: 0;
                margin-left: auto;
            }

            .fm-bar-file-text {
                display: flex;
                flex-direction: column;
                min-width: 0;
                line-height: 1.25;
            }

            .fm-bar-file-text strong {
                max-width: 34vw;
                overflow: hidden;
                color: var(--fm-ink);
                font-size: 13.5px;
                font-weight: 600;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-bar-file-text small {
                display: flex;
                align-items: center;
                gap: 6px;
                overflow: hidden;
                color: var(--fm-muted);
                font-size: 12px;
                white-space: nowrap;
            }

            .fm-bar-file-text .fm-editor-state {
                font-size: 12px;
            }

            .fm-bar-sep {
                opacity: .6;
            }

            .fm-bar-chip {
                padding: 0 7px;
                border: 0;
                border-radius: 999px;
                font-size: 11.5px;
                font-weight: 600;
                line-height: 18px;
                cursor: pointer;
            }

            .fm-bar-chip.is-warn {
                background: var(--fm-warning-soft);
                color: var(--fm-warning);
            }

            .fm-bar-file-actions {
                display: flex;
                flex-shrink: 0;
                align-items: center;
                gap: 4px;
            }

            .fm-inline-form {
                display: inline-flex;
                margin: 0;
            }

            .fm-topbar .fm-bar-dl i {
                color: var(--fm-ic-download);
            }

            .fm-topbar .fm-bar-edit i {
                color: var(--fm-ic-edit);
            }

            .fm-topbar .fm-bar-extract i {
                color: var(--fm-ic-zip);
            }

            .fm-topbar #js-editor-save kbd {
                margin-left: 2px;
            }

            .fm-topbar .fm-details-toggle {
                flex-shrink: 0;
            }

            .fm-topbar .fm-details-toggle i {
                color: var(--fm-accent);
            }

            .fm-topbar .fm-details-toggle[aria-expanded="true"] {
                border-color: color-mix(in srgb, var(--fm-accent) 40%, transparent);
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
            }

            :root {
                --fm-drawer-w: 380px;
            }

            .fm-drawer {
                position: fixed;
                top: var(--fm-topbar-h, 112px);
                right: 0;
                bottom: 0;
                z-index: 1025;
                display: flex;
                flex-direction: column;
                width: min(var(--fm-drawer-w), 100vw);
                border-left: 1px solid var(--fm-line);
                background: var(--fm-surface);
                box-shadow: -18px 0 40px -20px rgba(15, 23, 42, .45);
                transform: translateX(100%);
                visibility: hidden;
                transition: transform .22s ease, visibility 0s linear .22s;
            }

            .fm-drawer.is-open {
                transform: none;
                visibility: visible;
                transition: transform .22s ease;
            }

            body.fm-details-pinned .fm-drawer {
                box-shadow: none;
            }

            .fm-drawer-head {
                display: flex;
                align-items: center;
                gap: 4px;
                padding: 10px 12px 10px 18px;
                border-bottom: 1px solid var(--fm-line);
            }

            .fm-drawer-head h2 {
                flex: 1;
                margin: 0;
                font-size: 15px;
                font-weight: 650;
            }

            .fm-drawer-head h2 i {
                margin-right: 4px;
                color: var(--fm-accent);
            }

            .fm-drawer-btn {
                display: grid;
                place-items: center;
                width: 32px;
                height: 32px;
                padding: 0;
                border: 0;
                border-radius: 7px;
                background: none;
                color: var(--fm-muted);
            }

            .fm-drawer-btn:hover {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            .fm-drawer-pin {
                display: none;
            }

            .fm-drawer-pin[aria-pressed="true"] {
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
            }

            .fm-drawer-body {
                flex: 1;
                min-height: 0;
                padding: 16px 18px 20px;
                overflow-y: auto;
                overscroll-behavior: contain;
            }

            .fm-drawer-foot {
                margin: 0;
                padding: 9px 18px;
                border-top: 1px solid var(--fm-line);
                color: var(--fm-muted);
                font-size: 12px;
            }

            .fm-drawer-foot kbd {
                margin: 0 2px 0 6px;
                padding: 1px 6px;
                border: 1px solid var(--fm-line-strong);
                border-radius: 4px;
                background: var(--fm-tier);
                color: var(--fm-ink);
                font-family: var(--fm-mono);
                font-size: 11px;
                box-shadow: none;
            }

            .fm-drawer-foot kbd:first-child {
                margin-left: 0;
            }

            /* the page's own blocks, laid out for the narrow panel */
            .fm-drawer .fm-view-head {
                flex-direction: column;
                align-items: stretch;
                gap: 14px;
                margin-bottom: 14px;
            }

            .fm-drawer .fm-view-title {
                align-items: flex-start;
            }

            .fm-drawer .fm-view-title h1 {
                font-size: 17px;
                overflow-wrap: anywhere;
            }

            .fm-drawer .fm-view-title p {
                flex-wrap: wrap;
            }

            .fm-drawer .fm-path-chip {
                max-width: 100%;
                white-space: normal;
                overflow-wrap: anywhere;
            }

            .fm-drawer .fm-view-actions {
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 8px;
            }

            .fm-drawer .fm-view-actions > form,
            .fm-drawer .fm-view-actions > .btn-group {
                display: flex;
                margin: 0;
            }

            .fm-drawer .fm-view-actions .btn {
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 6px;
                width: 100%;
                padding-right: 8px;
                padding-left: 8px;
            }

            .fm-drawer .fm-view-actions .btn-group > .btn:first-child {
                flex: 1;
            }

            .fm-drawer .fm-view-actions .btn-group > .dropdown-toggle-split {
                flex: 0 0 34px;
                width: 34px;
            }

            .fm-drawer .fm-view-actions .fm-segmented {
                display: flex;
                grid-column: 1 / -1;
            }

            .fm-drawer .fm-view-actions .fm-segmented .nav-link {
                flex: 1;
                justify-content: center;
            }

            .fm-drawer .fm-view-facts {
                grid-template-columns: 1fr 1fr;
                gap: 8px;
                margin-bottom: 14px;
            }

            .fm-drawer .fm-fact {
                min-width: 0;
                padding: 10px 12px;
            }

            .fm-drawer .fm-fact-value {
                overflow-wrap: anywhere;
            }

            .fm-drawer .fm-enc-card {
                margin: 0;
            }

            .fm-drawer .fm-enc-head {
                flex-wrap: wrap;
            }

            .fm-drawer .fm-enc-grid {
                grid-template-columns: 1fr 1fr;
            }

            .fm-drawer .fm-enc-grid > div + div {
                border-left: 0;
            }

            .fm-drawer .fm-enc-grid > div:nth-child(even) {
                border-left: 1px solid var(--fm-line);
            }

            .fm-drawer .fm-enc-grid > div:nth-child(n+3) {
                border-top: 1px solid var(--fm-line);
            }

            .fm-drawer .fm-encoding-note {
                flex-direction: column;
                align-items: stretch;
                margin: 0;
            }

            .fm-drawer .fm-encoding-text {
                flex: none;
            }

            /* the file itself gets the whole height under the top bar */
            .fm-view {
                display: flex;
                flex-direction: column;
                max-width: none;
                height: calc(100vh - var(--fm-topbar-h, 112px) - 32px);
                min-height: 360px;
            }

            .fm-view > .fm-preview {
                display: flex;
                flex: 1;
                flex-direction: column;
                min-height: 0;
                margin: 0;
            }

            .fm-view .fm-preview-body {
                flex: 1;
                min-height: 0;
                overflow: auto;
            }

            .fm-view .fm-preview-body.is-code {
                display: flex;
                flex-direction: column;
                overflow: hidden;
            }

            .fm-view .fm-preview-body.is-code pre,
            .fm-view .fm-preview-body.is-code pre.with-hljs,
            .fm-view .fm-preview-body.is-code > #js-file-content {
                flex: 1;
                max-height: none;
                min-height: 0;
            }

            .fm-view .fm-preview-image {
                align-items: center;
                height: 100%;
            }

            .fm-view .fm-preview-image .preview-img {
                max-width: 100%;
                max-height: calc(100vh - var(--fm-topbar-h, 112px) - 150px);
            }

            .fm-view .fm-preview-media video {
                max-height: calc(100vh - var(--fm-topbar-h, 112px) - 150px);
            }

            .fm-view .fm-archive-list {
                max-height: none;
            }

            .fm-view .fm-preview-frame {
                height: 100%;
                min-height: 0;
            }

            @media (min-width: 1400px) {
                .fm-drawer-pin {
                    display: grid;
                }

                body.fm-details-pinned .fm-view,
                body.fm-details-pinned .fm-editor-page {
                    margin-right: var(--fm-drawer-w);
                }
            }

            @media (max-width: 991.98px) {
                .fm-bar-file {
                    flex: 1 1 auto;
                    margin-left: 0;
                }

                .fm-bar-file-text strong {
                    max-width: 60vw;
                }
            }

            @media (max-width: 575.98px) {
                .fm-bar-file-actions .fm-btn span,
                .fm-details-toggle span,
                .fm-topbar #js-editor-save kbd,
                .fm-drawer-foot {
                    display: none;
                }

                .fm-bar-file {
                    flex-basis: 100%;
                    order: 5;
                }

                .fm-bar-file-text strong {
                    max-width: 80vw;
                }
            }

            @media (prefers-reduced-motion: reduce) {
                .fm-drawer,
                .fm-drawer.is-open {
                    transition: none;
                }
            }

            /* page name on the right of the action row */
            .fm-page-chip {
                display: inline-flex;
                align-items: center;
                gap: 8px;
                margin-left: auto;
                padding: 5px 12px;
                border-radius: 999px;
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-size: 13px;
                font-weight: 600;
                white-space: nowrap;
            }

            .fm-topbar .fm-btn-primary.is-active {
                box-shadow: inset 0 0 0 2px rgba(255, 255, 255, .35);
            }

            /* segmented control built from links (upload source) */
            .fm-segmented .nav-link,
            .fm-segmented .nav-link:visited {
                display: inline-flex;
                align-items: center;
                gap: 7px;
                padding: 6px 14px;
                border-radius: 6px;
                color: var(--fm-muted);
                font-size: 13.5px;
                font-weight: 500;
            }

            .fm-segmented .nav-link:hover {
                color: var(--fm-ink);
            }

            .fm-segmented .nav-link.active {
                background: var(--fm-surface);
                color: var(--fm-ink);
                box-shadow: var(--fm-shadow);
            }

            .fm-segmented .nav-link.active i.fa-desktop {
                color: var(--fm-accent);
            }

            .fm-segmented .nav-link.active i.fa-link {
                color: var(--fm-ic-link);
            }

            /* ---- upload ---- */
            .fm-upload-card {
                padding: 20px;
            }

            .fm-upload-card form.dropzone {
                min-height: 280px;
                margin: 0;
            }

            .fm-upload-card form.dropzone .dz-message .dz-button {
                padding: 0;
                border: 0;
                background: none;
                color: var(--fm-ink);
                font: inherit;
                font-size: 16px;
                font-weight: 600;
            }

            .fm-upload-card form.dropzone .dz-message::after {
                content: "Uploads start straight away";
                color: var(--fm-muted);
                font-size: 13px;
                font-weight: 400;
            }

            .fm-upload-card form.dropzone.dz-started {
                display: block;
                min-height: 0;
                padding: 8px;
                border-style: solid;
                background: var(--fm-surface);
            }

            .fm-upload-card form.dropzone.dz-started:hover {
                border-color: var(--fm-line-strong);
            }

            .fm-upload-card .dropzone .dz-preview {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 12px;
                width: 100%;
                min-height: 0;
                margin: 0;
                padding: 10px 12px;
                border-bottom: 1px solid var(--fm-line);
                background: transparent;
            }

            .fm-upload-card .dropzone .dz-preview:last-child {
                border-bottom: 0;
            }

            .fm-upload-card .dropzone .dz-preview:hover {
                z-index: auto;
            }

            .fm-upload-card .dropzone .dz-preview .dz-image {
                flex: 0 0 40px;
                width: 40px;
                height: 40px;
                border-radius: 8px;
                background: var(--fm-tier);
                box-shadow: inset 0 0 0 1px var(--fm-line);
            }

            .fm-upload-card .dropzone .dz-preview .dz-image img {
                width: 40px;
                height: 40px;
                object-fit: cover;
            }

            .fm-upload-card .dropzone .dz-preview:hover .dz-image img {
                filter: none;
                transform: none;
            }

            .fm-upload-card .dropzone .dz-preview .dz-details {
                position: static;
                display: flex;
                flex: 1;
                flex-direction: column;
                min-width: 0;
                padding: 0;
                opacity: 1;
                color: var(--fm-ink);
                font-size: 13px;
                line-height: 1.4;
                text-align: left;
            }

            .fm-upload-card .dropzone .dz-preview .dz-details .dz-filename {
                order: -1;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
                font-weight: 600;
            }

            .fm-upload-card .dropzone .dz-preview .dz-details .dz-size {
                margin: 0;
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-upload-card .dropzone .dz-preview .dz-details .dz-size strong {
                font-weight: 500;
            }

            .fm-upload-card .dropzone .dz-preview .dz-details .dz-filename span,
            .fm-upload-card .dropzone .dz-preview .dz-details .dz-size span,
            .fm-upload-card .dropzone .dz-preview .dz-details .dz-filename:hover span {
                padding: 0;
                border: 0;
                background: none;
            }

            .fm-upload-card .dropzone .dz-preview .dz-progress {
                position: static;
                flex: 0 0 160px;
                width: 160px;
                height: 6px;
                margin: 0;
                border-radius: 999px;
                background: var(--fm-tier);
                box-shadow: inset 0 0 0 1px var(--fm-line);
                opacity: 1;
            }

            .fm-upload-card .dropzone .dz-preview .dz-progress .dz-upload {
                border-radius: 999px;
                background: var(--fm-accent);
            }

            .fm-upload-card .dropzone .dz-preview.dz-success .dz-progress .dz-upload {
                background: var(--fm-success);
            }

            .fm-upload-card .dropzone .dz-preview.dz-complete .dz-progress {
                opacity: 1;
            }

            .fm-upload-card .dropzone .dz-preview .dz-success-mark,
            .fm-upload-card .dropzone .dz-preview .dz-error-mark {
                display: none;
            }

            .fm-upload-card .dropzone .dz-preview::after {
                flex: 0 0 18px;
                font: normal normal normal 16px/1 FontAwesome;
                content: "\f110";
                color: var(--fm-muted);
                text-align: center;
            }

            .fm-upload-card .dropzone .dz-preview.dz-success::after {
                content: "\f058";
                color: var(--fm-success);
            }

            .fm-upload-card .dropzone .dz-preview.dz-error::after {
                content: "\f06a";
                color: var(--fm-danger);
            }

            .fm-upload-card .dropzone .dz-preview .dz-error-message {
                position: static;
                display: none;
                flex-basis: 100%;
                width: auto;
                margin: 0 0 0 52px;
                padding: 0;
                border-radius: 0;
                background: none;
                color: var(--fm-danger);
                font-size: 12.5px;
                opacity: 1;
                pointer-events: auto;
            }

            .fm-upload-card .dropzone .dz-preview .dz-error-message::after {
                display: none;
            }

            .fm-upload-card .dropzone .dz-preview.dz-error .dz-error-message {
                display: block;
            }

            /* Dropzone's own stylesheet loads after ours, so these need the extra form selector */
            .fm-upload-card form.dropzone .dz-preview .dz-image,
            .fm-upload-card form.dropzone .dz-preview.dz-file-preview .dz-image {
                display: grid;
                place-items: center;
                border-radius: 8px;
                background: var(--fm-tier);
            }

            .fm-upload-card form.dropzone .dz-preview.dz-file-preview .dz-image img {
                display: none;
            }

            .fm-upload-card form.dropzone .dz-preview.dz-file-preview .dz-image::before {
                font: normal normal normal 17px/1 FontAwesome;
                content: "\f016";
                color: var(--fm-muted);
            }

            .fm-upload-card form.dropzone .dz-preview::after {
                order: 5;
            }

            .fm-upload-card form.dropzone .dz-preview .dz-error-message {
                order: 10;
            }

            .fm-upload-card form.dropzone .dz-preview.dz-error .dz-progress {
                visibility: hidden;
            }

            .fm-upload-limits {
                display: flex;
                flex-wrap: wrap;
                gap: 8px 22px;
                margin-top: 14px;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-upload-limits span {
                display: inline-flex;
                align-items: center;
                gap: 7px;
            }

            .fm-upload-limits i {
                color: var(--fm-muted);
            }

            .fm-upload-limits strong {
                color: var(--fm-ink);
                font-weight: 600;
            }

            /* icon-in-input field + inline forms (URL upload, password hash) */
            .fm-tool-form {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 10px;
            }

            .fm-input-icon {
                position: relative;
                display: flex;
                align-items: center;
                flex: 1 1 280px;
            }

            .fm-input-icon > i {
                position: absolute;
                left: 13px;
                color: var(--fm-muted);
                pointer-events: none;
            }

            .fm-input-icon .form-control {
                height: 42px;
                padding-left: 38px;
            }

            .fm-input-reveal {
                position: absolute;
                right: 6px;
                padding: 4px 8px;
                border: 0;
                border-radius: 6px;
                background: transparent;
                color: var(--fm-muted);
            }

            .fm-input-reveal:hover {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            .fm-tool-form > .btn {
                height: 42px;
                padding: 0 18px;
            }

            .fm-url-hint {
                margin: 10px 0 0;
                font-size: 13px;
            }

            .fm-upload-wrapper .card-tabs-container.hidden {
                display: none !important;
            }

            .fm-url-results:not(:empty) {
                margin-top: 16px;
            }

            .fm-url-head {
                display: flex;
                align-items: center;
                justify-content: space-between;
                margin-bottom: 8px;
                color: var(--fm-muted);
                font-size: 13px;
                font-weight: 600;
            }

            .fm-url-head .btn-link {
                padding: 0;
                font-size: 13px;
            }

            .fm-url-result {
                display: flex;
                align-items: center;
                gap: 12px;
                padding: 12px 14px;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                background: var(--fm-surface);
                font-size: 13.5px;
                transition: border-color .2s, background-color .2s;
            }

            .fm-url-result + .fm-url-result {
                margin-top: 8px;
            }

            .fm-url-icon {
                display: grid;
                place-items: center;
                flex: 0 0 38px;
                width: 38px;
                height: 38px;
                border-radius: 10px;
                background: var(--fm-tier);
                font-size: 17px;
            }

            .fm-url-result.is-busy .fm-url-icon {
                color: var(--fm-accent);
            }

            .fm-url-result.is-error {
                border-color: color-mix(in srgb, var(--fm-danger) 35%, var(--fm-line));
                background: var(--fm-danger-soft);
            }

            .fm-url-result.is-error .fm-url-icon {
                background: var(--fm-surface);
                color: var(--fm-danger);
            }

            .fm-url-result .fm-url-icon i.fa-file-o {
                color: var(--fm-muted);
            }

            .fm-url-text {
                display: flex;
                flex: 1;
                flex-direction: column;
                gap: 2px;
                min-width: 0;
            }

            .fm-url-text strong {
                overflow: hidden;
                color: var(--fm-ink);
                font-weight: 600;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-url-text small {
                color: var(--fm-muted);
                font-size: 12.5px;
                word-break: break-all;
            }

            .fm-url-result.is-ok .fm-url-text small i {
                color: var(--fm-success);
            }

            .fm-url-result.is-error .fm-url-text small:first-of-type {
                color: var(--fm-ink);
            }

            .fm-url-src {
                font-family: var(--fm-mono);
                font-size: 11.5px !important;
            }

            .fm-url-tag {
                display: inline-flex;
                align-items: center;
                gap: 6px;
                align-self: flex-start;
                margin-top: 4px;
                padding: 2px 8px;
                border-radius: 999px;
                background: var(--fm-warning-soft);
                color: var(--fm-warning);
                font-size: 12px;
                font-weight: 600;
            }

            .fm-url-result > .btn {
                flex: 0 0 auto;
                background: var(--fm-surface);
            }

            .fm-url-result > .btn i.fa-eye {
                color: var(--fm-accent);
            }

            #js-form-url-upload > .btn i.fa {
                color: inherit;
            }

            /* ---- settings ---- */
            .fm-settings {
                padding: 0;
            }

            .fm-settings-group {
                padding: 8px 24px 4px;
            }

            .fm-settings-group + .fm-settings-group {
                border-top: 1px solid var(--fm-line);
            }

            .fm-settings-group h2 {
                margin: 16px 0 4px;
                color: var(--fm-muted);
                font-size: 13px;
                font-weight: 600;
            }

            .fm-setting {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 24px;
                padding: 14px 0;
            }

            .fm-setting + .fm-setting {
                border-top: 1px dashed var(--fm-line);
            }

            .fm-setting-text {
                display: flex;
                flex-direction: column;
                gap: 2px;
                min-width: 0;
                margin: 0;
                cursor: default;
            }

            label.fm-setting-text {
                cursor: pointer;
            }

            .fm-setting-name {
                color: var(--fm-ink);
                font-weight: 600;
            }

            .fm-setting-desc {
                color: var(--fm-muted);
                font-size: 13px;
                font-weight: 400;
            }

            .fm-setting-desc code {
                padding: 1px 5px;
                border-radius: 4px;
                background: var(--fm-tier);
                color: var(--fm-ink);
                font-size: 12px;
            }

            .fm-setting-select {
                flex: 0 0 220px;
                width: 220px;
            }

            .fm-switch {
                flex: 0 0 auto;
                margin: 0;
                padding: 0;
                min-height: 0;
            }

            .fm-switch .form-check-input {
                width: 42px;
                height: 24px;
                margin: 0;
                cursor: pointer;
            }

            .fm-settings .fm-segmented input:checked + label i.fa-sun-o {
                color: var(--fm-ic-edit);
            }

            .fm-settings .fm-segmented input:checked + label i.fa-moon-o {
                color: var(--fm-ic-tar);
            }

            .fm-settings-foot {
                display: flex;
                align-items: center;
                justify-content: flex-end;
                gap: 8px;
                padding: 14px 24px;
                border-top: 1px solid var(--fm-line);
                background: var(--fm-tier);
            }

            .fm-save-status {
                display: inline-flex;
                align-items: center;
                gap: 7px;
                margin-right: auto;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-save-status.is-ok,
            .fm-save-status.is-ok i {
                color: var(--fm-success);
            }

            .fm-save-status.is-error,
            .fm-save-status.is-error i {
                color: var(--fm-danger);
            }

            /* ---- help ---- */
            /* 3 x 2 cards at the shared page width; icon beside the title keeps the page within one screen */
            .fm-help-grid {
                display: grid;
                grid-template-columns: repeat(3, minmax(0, 1fr));
                gap: 12px;
                margin-bottom: 14px;
            }

            .fm-help-card {
                display: grid;
                grid-template-columns: 38px minmax(0, 1fr);
                align-items: center;
                column-gap: 12px;
                padding: 14px 18px;
            }

            .fm-help-card > p {
                grid-column: 1 / -1;
                margin-top: 8px !important;
            }

            @media (max-width: 1100px) {
                .fm-help-grid {
                    grid-template-columns: repeat(2, minmax(0, 1fr));
                }
            }

            @media (max-width: 700px) {
                .fm-help-grid {
                    grid-template-columns: minmax(0, 1fr);
                }
            }

            .fm-help-card h2,
            .fm-tool-head h2 {
                margin: 12px 0 6px;
                font-size: 15px;
                font-weight: 600;
            }

            .fm-help-card p,
            .fm-tool-head p {
                margin: 0;
                color: var(--fm-muted);
                font-size: 13.5px;
                line-height: 1.55;
            }

            .fm-help-card p strong {
                color: var(--fm-ink);
                font-weight: 600;
            }

            .fm-help-card > h2 {
                margin: 0;
            }

            .fm-help-card code {
                padding: 1px 5px;
                border-radius: 4px;
                background: var(--fm-tier);
                color: var(--fm-ink);
                font-size: 12px;
            }

            .fm-help-icon {
                display: grid;
                place-items: center;
                width: 38px;
                height: 38px;
                border-radius: 10px;
                font-size: 17px;
            }

            .fm-help-icon.is-upload { background: var(--fm-accent-soft); color: var(--fm-accent); }
            .fm-help-icon.is-select { background: var(--fm-accent-soft); color: var(--fm-ic-select); }
            .fm-help-icon.is-copy { background: color-mix(in srgb, var(--fm-ic-copy) 14%, transparent); color: var(--fm-ic-copy); }
            .fm-help-icon.is-zip { background: var(--fm-zip-soft); color: var(--fm-ic-zip); }
            .fm-help-icon.is-search { background: color-mix(in srgb, var(--fm-ic-link) 14%, transparent); color: var(--fm-ic-link); }
            .fm-help-icon.is-edit { background: color-mix(in srgb, var(--fm-ic-edit) 14%, transparent); color: var(--fm-ic-edit); }
            .fm-help-icon.is-lock { background: var(--fm-tar-soft); color: var(--fm-ic-tar); }

            .fm-help-icon i.fa {
                color: inherit !important;
            }

            .fm-tool-card {
                padding: 20px 22px;
            }

            .fm-tool-head {
                display: flex;
                align-items: flex-start;
                gap: 14px;
                margin-bottom: 16px;
            }

            .fm-tool-head h2 {
                margin-top: 0;
            }

            .fm-tool-result {
                margin-top: 16px;
            }

            .fm-result-row {
                display: flex;
                gap: 10px;
            }

            .fm-result-row .form-control {
                height: 42px;
                background: var(--fm-tier);
                font-family: var(--fm-mono);
                font-size: 13px;
            }

            .fm-result-row .btn {
                flex: 0 0 auto;
                height: 42px;
            }

            @media (max-width: 767.98px) {
                .fm-page-chip {
                    display: none;
                }

                .fm-setting {
                    flex-wrap: wrap;
                    gap: 10px;
                }

                .fm-setting-select {
                    flex-basis: 100%;
                    width: 100%;
                }

                .fm-upload-card .dropzone .dz-preview .dz-progress {
                    flex-basis: 100%;
                    width: 100%;
                }
            }

            /* ---- permissions (same two-card layout as the copy page) ---- */
            .fm-perms-owner {
                display: flex;
                flex-wrap: wrap;
                gap: 6px;
                margin: 0;
            }

            .fm-perms-owner span {
                display: inline-flex;
                align-items: center;
                gap: 6px;
                padding: 3px 10px;
                border: 1px solid var(--fm-line);
                border-radius: 999px;
                background: var(--fm-tier);
                color: var(--fm-ink);
                font-family: var(--fm-mono);
                font-size: 12.5px;
            }

            .fm-perms-owner i {
                color: var(--fm-muted);
            }

            .fm-perms-compare {
                display: flex;
                align-items: stretch;
                gap: 10px;
            }

            .fm-perms-code {
                display: grid;
                flex: 1;
                gap: 3px;
                padding: 10px 12px;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                background: var(--fm-tier);
            }

            .fm-perms-tag {
                color: var(--fm-muted);
                font-size: 11px;
                font-weight: 650;
                letter-spacing: .06em;
                text-transform: uppercase;
            }

            .fm-perms-octal {
                color: var(--fm-ink);
                font-family: var(--fm-mono);
                font-size: 24px;
                font-weight: 700;
                line-height: 1.1;
            }

            .fm-perms-symbolic {
                color: var(--fm-muted);
                font-family: var(--fm-mono);
                font-size: 13px;
                letter-spacing: .08em;
            }

            .fm-perms-arrow {
                align-self: center;
                color: var(--fm-muted);
            }

            .fm-perms-code.is-new.is-changed {
                border-color: color-mix(in srgb, var(--fm-accent) 50%, var(--fm-line));
                background: var(--fm-accent-soft);
            }

            .fm-perms-code.is-new.is-changed .fm-perms-octal {
                color: var(--fm-accent);
            }

            .fm-perms-special {
                display: flex;
                align-items: flex-start;
                gap: 8px;
                margin: 12px 0 0;
                font-size: 13px;
            }

            .fm-perms-special i {
                margin-top: 3px;
            }

            .fm-perms-presets {
                display: flex;
                flex-wrap: wrap;
                gap: 6px;
            }

            .fm-preset {
                display: inline-flex;
                align-items: baseline;
                gap: 6px;
                padding: 6px 11px;
                border: 1px solid var(--fm-line-strong);
                border-radius: 999px;
                background: var(--fm-surface);
                color: var(--fm-ink);
                font-family: var(--fm-mono);
                font-size: 13px;
                font-weight: 600;
                transition: border-color .15s, background-color .15s;
            }

            .fm-preset small {
                color: var(--fm-muted);
                font-family: var(--bs-body-font-family);
                font-size: 12px;
                font-weight: 500;
            }

            .fm-preset:hover {
                border-color: var(--fm-accent);
            }

            .fm-preset.is-active {
                border-color: var(--fm-accent);
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
            }

            .fm-perms-matrix {
                display: grid;
                grid-template-columns: minmax(0, 1fr) repeat(3, 84px);
                align-items: center;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                overflow: hidden;
            }

            .fm-perms-matrix > * {
                align-self: stretch;
                min-height: 54px;
                padding: 8px 12px;
                border-top: 1px solid var(--fm-line);
            }

            .fm-perms-matrix > :nth-child(-n+4) {
                min-height: 0;
                border-top: 0;
                background: var(--fm-tier);
            }

            .fm-perms-colhead {
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                gap: 2px;
                color: var(--fm-ink);
                font-size: 12.5px;
                font-weight: 600;
                cursor: help;
            }

            .fm-perms-colhead i {
                color: var(--fm-muted);
            }

            .fm-perms-rowhead {
                display: flex;
                flex-direction: column;
                justify-content: center;
                min-width: 0;
                line-height: 1.35;
            }

            .fm-perms-rowhead strong {
                color: var(--fm-ink);
                font-size: 14px;
                font-weight: 600;
            }

            .fm-perms-rowhead strong i {
                width: 20px;
                color: var(--fm-accent);
            }

            .fm-perms-rowhead small {
                padding-left: 20px;
                color: var(--fm-muted);
                font-size: 12px;
            }

            .fm-perm-cell {
                position: relative;
                display: flex;
                align-items: center;
                justify-content: center;
                align-self: stretch;
                margin: 0;
                cursor: pointer;
                transition: background-color .15s;
            }

            .fm-perm-cell:hover {
                background: var(--fm-tier);
            }

            .fm-perm-cell input {
                position: absolute;
                opacity: 0;
                pointer-events: none;
            }

            .fm-perm-switch {
                position: relative;
                width: 36px;
                height: 20px;
                border-radius: 999px;
                background: var(--fm-line-strong);
                transition: background-color .15s;
            }

            .fm-perm-switch::after {
                content: "";
                position: absolute;
                top: 2px;
                left: 2px;
                width: 16px;
                height: 16px;
                border-radius: 50%;
                background: #FFFFFF;
                box-shadow: 0 1px 2px rgba(0, 0, 0, .25);
                transition: transform .15s;
            }

            .fm-perm-cell input:checked ~ .fm-perm-switch {
                background: var(--fm-accent);
            }

            .fm-perm-cell input:checked ~ .fm-perm-switch::after {
                transform: translateX(16px);
            }

            .fm-perm-cell.is-risky input:checked ~ .fm-perm-switch {
                background: var(--fm-danger-solid);
            }

            .fm-perm-cell input:focus-visible ~ .fm-perm-switch {
                box-shadow: var(--fm-focus);
            }

            .fm-perms-legend {
                display: grid;
                gap: 3px;
                margin: 10px 0 0;
                padding: 0;
                list-style: none;
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-perms-legend i {
                width: 18px;
            }

            .fm-perms-legend strong {
                color: var(--fm-ink);
                font-weight: 600;
            }

            .fm-perms-warning {
                display: flex;
                align-items: flex-start;
                gap: 10px;
                margin-top: 14px;
                padding: 11px 13px;
                border: 1px solid color-mix(in srgb, var(--fm-danger) 35%, transparent);
                border-radius: 8px;
                background: var(--fm-danger-soft);
                font-size: 13.5px;
            }

            .fm-perms-warning[hidden] {
                display: none;
            }

            .fm-perms-warning i,
            .fm-perms-warning strong {
                color: var(--fm-danger);
            }

            .fm-perms-warning i {
                margin-top: 2px;
            }

            .fm-perms-foot {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                justify-content: space-between;
                gap: 10px;
                margin-top: 16px;
                padding-top: 14px;
                border-top: 1px solid var(--fm-line);
            }

            .fm-perms-number {
                display: flex;
                align-items: center;
                gap: 8px;
                margin: 0;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-perms-number .form-control {
                width: 80px;
                height: 36px;
                font-family: var(--fm-mono);
                font-size: 15px;
                font-weight: 600;
                text-align: center;
                letter-spacing: .1em;
            }

            .fm-perms-number .form-control.is-invalid {
                border-color: var(--fm-danger);
                box-shadow: 0 0 0 3px color-mix(in srgb, var(--fm-danger) 25%, transparent);
            }

            .fm-perms .fm-copy-panel .fm-card-actions {
                margin-top: 14px;
            }

            #js-perm-submit:disabled {
                opacity: .5;
            }

            @media (max-width: 575.98px) {
                .fm-perms-matrix {
                    grid-template-columns: minmax(0, 1fr) repeat(3, 58px);
                }

                .fm-perms-matrix > * {
                    padding: 8px;
                }

                .fm-perms-rowhead small {
                    display: none;
                }
            }

            /* ---- new item ---- */
            .fm-new-title i {
                color: var(--fm-ic-create);
                margin-right: 4px;
            }

            .fm-choice-row {
                grid-template-columns: 1fr 1fr;
            }

            .fm-choice-row .fm-choice-item small {
                word-break: normal;
            }

            .fm-choice-row .fm-choice-item > i.fa-file-text-o {
                color: var(--fm-ic-copy);
            }

            .fm-new-name-label {
                margin-top: 18px;
            }

            .fm-new-dest {
                color: var(--fm-ink);
                font-family: var(--fm-mono);
                font-size: 12.5px;
                word-break: break-all;
            }

            #createNewItem .modal-dialog {
                max-width: 500px;
            }

            #js-new-submit:disabled {
                opacity: .5;
            }

            @media (max-width: 575.98px) {
                .fm-choice-row {
                    grid-template-columns: 1fr;
                }
            }

            /* ---- file view ---- */
            /* full width and no page margins: the file fills the space under the top bar exactly */
            .fm-page.fm-view {
                max-width: none;
                margin: 0;
            }

            .fm-view-head {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                justify-content: space-between;
                gap: 16px;
                margin-bottom: 16px;
            }

            .fm-view-title {
                display: flex;
                align-items: center;
                gap: 14px;
                min-width: 0;
            }

            .fm-view-title > div {
                min-width: 0;
            }

            .fm-view-icon {
                display: grid;
                place-items: center;
                flex: 0 0 52px;
                width: 52px;
                height: 52px;
                border: 1px solid var(--fm-line);
                border-radius: 14px;
                background: var(--fm-surface);
                box-shadow: var(--fm-shadow);
                font-size: 24px;
            }

            .fm-view-icon i.fa-file-o,
            .fm-view-icon i.fa-file-text-o {
                color: var(--fm-muted);
            }

            .fm-view-title h1 {
                margin: 0 0 4px;
                font-size: 21px;
                font-weight: 650;
                letter-spacing: -.01em;
                word-break: break-all;
            }

            .fm-view-title p {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 8px;
                margin: 0;
            }

            .fm-view-kind {
                padding: 2px 9px;
                border-radius: 999px;
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-size: 12.5px;
                font-weight: 600;
            }

            .fm-view-actions {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 8px;
            }

            .fm-view-actions .btn {
                height: 36px;
            }

            .fm-view-actions .btn-primary i.fa {
                color: inherit;
            }

            .fm-view-actions .btn i.fa-globe {
                color: var(--fm-accent);
            }

            .fm-view-actions .btn i.fa-external-link {
                color: var(--fm-ic-link);
            }

            .fm-view-actions .btn i.fa-pencil {
                color: var(--fm-ic-edit);
            }

            .fm-view-actions .dropdown-toggle-split {
                padding: 0 10px;
            }

            .fm-view-facts {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
                gap: 10px;
                margin-bottom: 16px;
            }

            .fm-fact {
                display: flex;
                flex-direction: column;
                gap: 4px;
                padding: 12px 14px;
                border: 1px solid var(--fm-line);
                border-radius: 12px;
                background: var(--fm-surface);
                box-shadow: var(--fm-shadow);
                min-width: 0;
            }

            .fm-fact-label {
                color: var(--fm-muted);
                font-size: 12.5px;
                font-weight: 500;
            }

            .fm-fact-label i {
                width: 14px;
                margin-right: 2px;
                color: var(--fm-muted);
            }

            .fm-fact-value {
                color: var(--fm-ink);
                font-size: 14.5px;
                font-weight: 600;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-preview {
                padding: 0;
            }

            .fm-preview-head {
                display: flex;
                align-items: center;
                gap: 12px;
                padding: 12px 18px;
                border-bottom: 1px solid var(--fm-line);
            }

            .fm-preview-head h2 {
                margin: 0;
                font-size: 15px;
                font-weight: 600;
            }

            .fm-preview-meta {
                color: var(--fm-muted);
                font-size: 13px;
            }

            /* right-to-left text in the preview */
            .fm-dir-auto #js-file-content,
            .fm-dir-auto #js-file-content code {
                unicode-bidi: plaintext;
                text-align: start;
            }

            .fm-dir-rtl #js-file-content,
            .fm-dir-rtl #js-file-content code {
                direction: rtl;
                text-align: right;
            }

            /* fixed-width fonts stretch Arabic letters into equal cells; right-to-left text reads better proportional */
            .fm-dir-auto #js-file-content,
            .fm-dir-auto #js-file-content code,
            .fm-dir-rtl #js-file-content,
            .fm-dir-rtl #js-file-content code {
                font-family: "Segoe UI", Tahoma, "Noto Sans Arabic", "Noto Naskh Arabic", "Noto Sans", "Geeza Pro", Arial, sans-serif;
                font-size: 15px;
                line-height: 1.85;
            }

            .fm-dir-switch {
                display: inline-flex;
                margin-left: auto;
                padding: 2px;
                border: 1px solid var(--fm-line);
                border-radius: 8px;
                background: var(--fm-tier);
            }

            .fm-dir-switch button {
                padding: 2px 10px;
                border: 0;
                border-radius: 6px;
                background: none;
                color: var(--fm-muted);
                font-size: 12px;
                font-weight: 600;
            }

            .fm-dir-switch button[aria-pressed="true"] {
                background: var(--fm-surface);
                color: var(--fm-accent);
                box-shadow: 0 1px 2px rgba(15, 23, 42, .12);
            }

            .fm-dir-switch + .btn {
                margin-left: 0 !important;
            }

            .fm-preview-head .btn {
                margin-left: auto;
            }

            .fm-preview-body {
                padding: 18px;
            }

            .fm-preview-body.is-code {
                padding: 0;
            }

            .fm-preview-body.is-code pre,
            .fm-preview-body.is-code pre.with-hljs {
                max-height: 70vh;
                margin: 0;
                overflow: auto;
                border: 0;
                border-radius: 0 0 12px 12px;
                box-shadow: none;
            }

            /* the box scrolls; the code inside must not show its own scrollbars */
            .fm-preview-body.is-code pre.with-hljs code {
                overflow: visible;
            }

            .fm-preview-body.is-code pre:not(.with-hljs),
            .fm-preview-body.is-code > #js-file-content {
                padding: 16px;
                font-family: var(--fm-mono);
                font-size: 13px;
                max-height: 70vh;
                overflow: auto;
            }

            .fm-preview-image {
                display: flex;
                justify-content: center;
                padding: 16px;
                border-radius: 10px;
                background-color: var(--fm-tier);
                background-image: linear-gradient(45deg, var(--fm-line) 25%, transparent 25%), linear-gradient(-45deg, var(--fm-line) 25%, transparent 25%), linear-gradient(45deg, transparent 75%, var(--fm-line) 75%), linear-gradient(-45deg, transparent 75%, var(--fm-line) 75%);
                background-size: 20px 20px;
                background-position: 0 0, 0 10px, 10px -10px, -10px 0;
                overflow: auto;
            }

            .fm-preview-image .preview-img {
                max-height: 70vh;
                border: 0;
                border-radius: 6px;
                background: none;
                box-shadow: var(--fm-shadow-lg);
            }

            .fm-preview-media {
                display: flex;
                justify-content: center;
            }

            .fm-preview-media audio {
                width: 100%;
                max-width: 640px;
            }

            .fm-preview-media video {
                width: 100%;
                max-height: 70vh;
                border-radius: 10px;
                background: #000;
            }

            .fm-preview-frame {
                width: 100%;
                min-height: 70vh;
                border-radius: 10px;
            }

            .fm-archive-list {
                max-height: 60vh;
                margin: 0;
                padding: 0;
                overflow-y: auto;
                list-style: none;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
            }

            .fm-archive-list li {
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 8px 14px;
                font-size: 13.5px;
            }

            .fm-archive-list li + li {
                border-top: 1px solid var(--fm-line);
            }

            .fm-archive-list li:nth-child(even) {
                background: var(--fm-tier);
            }

            .fm-archive-list li > i {
                width: 16px;
                color: var(--fm-muted);
                text-align: center;
            }

            .fm-archive-list li.is-folder > i {
                color: var(--fm-folder);
            }

            .fm-archive-list li.is-folder span {
                font-weight: 600;
            }

            .fm-archive-list li span {
                min-width: 0;
                word-break: break-all;
            }

            .fm-archive-list li small {
                margin-left: auto;
                padding-left: 12px;
                color: var(--fm-muted);
                white-space: nowrap;
                font-variant-numeric: tabular-nums;
            }

            @media (max-width: 767.98px) {
                .fm-view-actions {
                    width: 100%;
                }

                .fm-view-title {
                    align-items: flex-start;
                }

                .fm-view-icon {
                    flex-basis: 40px;
                    width: 40px;
                    height: 40px;
                    border-radius: 11px;
                    font-size: 18px;
                }
            }

            /* ---- file editor: fills the space under the sticky bar, never behind it ---- */
            .fm-editor-page {
                display: flex;
                flex-direction: column;
                height: calc(100vh - var(--fm-topbar-h, 112px) - 32px);
                min-height: 460px;
                max-width: none;
            }


            .fm-editor-state {
                display: inline-flex;
                align-items: center;
                gap: 6px;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-editor-state i {
                color: var(--fm-success);
            }

            .fm-editor-state.is-dirty {
                color: var(--fm-warning);
                font-weight: 600;
            }

            .fm-editor-state.is-dirty i {
                color: var(--fm-warning);
                font-size: 9px;
            }

            #js-editor-save kbd {
                padding: 1px 5px;
                border-radius: 4px;
                background: rgba(255, 255, 255, .2);
                color: inherit;
                font-family: var(--fm-mono);
                font-size: 11px;
                box-shadow: none;
            }

            .fm-editor-card {
                display: flex;
                flex: 1;
                flex-direction: column;
                min-height: 0;
                padding: 0;
            }

            .fm-editor-toolbar {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                justify-content: space-between;
                gap: 8px 16px;
                padding: 8px 10px;
                border-bottom: 1px solid var(--fm-line);
                background: var(--fm-tier);
                border-radius: 12px 12px 0 0;
                box-shadow: none;
            }

            .fm-editor-tools {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 2px;
            }

            .fm-tool {
                display: inline-flex;
                align-items: center;
                gap: 7px;
                height: 32px;
                padding: 0 10px;
                border: 1px solid transparent;
                border-radius: 7px;
                background: transparent;
                color: var(--fm-ink);
                font-size: 13px;
                font-weight: 500;
            }

            .fm-tool i {
                color: var(--fm-muted);
            }

            .fm-tool:hover {
                background: var(--fm-hover);
            }

            .fm-tool.is-on {
                border-color: color-mix(in srgb, var(--fm-accent) 40%, transparent);
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
            }

            .fm-tool.is-on i {
                color: var(--fm-accent);
            }

            .fm-editor-selects {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 10px;
            }

            .fm-editor-selects label {
                display: inline-flex;
                align-items: center;
                gap: 6px;
                margin: 0;
                color: var(--fm-muted);
                font-size: 12.5px;
                font-weight: 500;
            }

            .fm-editor-selects .form-select {
                width: auto;
                min-width: 90px;
                max-width: 170px;
                height: 32px;
                padding-top: 0;
                padding-bottom: 0;
                font-size: 13px;
            }

            .fm-editor-card #editor {
                position: relative;
                flex: 1;
                min-height: 0;
                margin: 0;
                border: 0;
                border-radius: 0;
                font-size: 14px;
            }

            .fm-editor-card #normal-editor {
                flex: 1;
                min-height: 0;
                width: 100%;
                margin: 0;
                padding: 16px 18px;
                border: 0;
                border-radius: 12px 12px 0 0;
                background: var(--fm-surface);
                color: var(--fm-ink);
                font-family: var(--fm-mono);
                font-size: 14px;
                line-height: 1.6;
                tab-size: 4;
                resize: none;
                box-shadow: none;
            }

            .fm-editor-card #normal-editor:focus {
                outline: none;
                box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--fm-accent) 35%, transparent);
            }

            .fm-editor-status {
                display: flex;
                flex-wrap: wrap;
                gap: 6px 18px;
                padding: 7px 14px;
                border-top: 1px solid var(--fm-line);
                background: var(--fm-tier);
                border-radius: 0 0 12px 12px;
                color: var(--fm-muted);
                font-size: 12.5px;
                font-variant-numeric: tabular-nums;
            }

            .fm-editor-saved {
                margin-left: auto;
                color: var(--fm-success);
            }

            /* fullscreen editor covers everything, including the sticky bar */
            #editor:fullscreen {
                height: 100vh;
                border-radius: 0;
            }

            @media (max-width: 767.98px) {
                .fm-editor-page {
                    height: auto;
                }

                .fm-editor-card {
                    min-height: 70vh;
                }

                .fm-editor-card #editor,
                .fm-editor-card #normal-editor {
                    min-height: 60vh;
                }

                .fm-tool span {
                    display: none;
                }
            }

            /* ---- non-UTF-8 notice in the editor ---- */
            .fm-encoding-note {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 10px 14px;
                margin-bottom: 12px;
                padding: 11px 14px;
                border: 1px solid color-mix(in srgb, var(--fm-warning) 40%, transparent);
                border-radius: 10px;
                background: var(--fm-warning-soft);
                font-size: 13.5px;
            }

            .fm-encoding-note > i {
                color: var(--fm-warning);
                font-size: 18px;
            }

            .fm-encoding-text {
                display: flex;
                flex: 1 1 320px;
                flex-direction: column;
            }

            .fm-encoding-text span {
                color: var(--fm-muted);
            }

            .fm-encoding-controls {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 8px 14px;
            }

            .fm-encoding-controls label {
                display: inline-flex;
                align-items: center;
                gap: 8px;
                margin: 0;
                color: var(--fm-ink);
                font-size: 13px;
                font-weight: 500;
            }

            .fm-encoding-controls .form-select {
                width: auto;
                height: 32px;
                padding-top: 0;
                padding-bottom: 0;
            }

            /* ---- encoding card (file view) ---- */
            .fm-enc-card {
                margin-bottom: 16px;
                padding: 0;
            }

            .fm-enc-head {
                display: flex;
                align-items: flex-start;
                gap: 14px;
                padding: 16px 18px;
            }

            .fm-enc-icon {
                display: grid;
                place-items: center;
                flex: 0 0 38px;
                width: 38px;
                height: 38px;
                border-radius: 10px;
                background: var(--fm-success-soft);
                color: var(--fm-success);
                font-size: 17px;
            }

            .fm-enc-card.is-warn .fm-enc-icon {
                background: var(--fm-warning-soft);
                color: var(--fm-warning);
            }

            .fm-enc-card.is-binary .fm-enc-icon {
                background: var(--fm-tier);
                color: var(--fm-muted);
            }

            .fm-enc-icon i.fa {
                color: inherit !important;
            }

            .fm-enc-summary {
                flex: 1;
                min-width: 0;
            }

            .fm-enc-summary h2 {
                margin: 0 0 3px;
                color: var(--fm-muted);
                font-size: 13px;
                font-weight: 500;
            }

            .fm-enc-summary h2 strong {
                margin-left: 6px;
                color: var(--fm-ink);
                font-size: 16px;
                font-weight: 650;
            }

            .fm-enc-summary p {
                margin: 0;
                color: var(--fm-muted);
                font-size: 13.5px;
                line-height: 1.5;
            }

            .fm-enc-head .btn {
                flex: 0 0 auto;
            }

            .fm-enc-grid {
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
                margin: 0;
                border-top: 1px solid var(--fm-line);
                background: var(--fm-tier);
                border-radius: 0 0 12px 12px;
            }

            .fm-enc-grid > div {
                padding: 10px 18px;
            }

            .fm-enc-grid > div + div {
                border-left: 1px solid var(--fm-line);
            }

            .fm-enc-grid dt {
                color: var(--fm-muted);
                font-size: 12px;
                font-weight: 500;
            }

            .fm-enc-grid dd {
                margin: 2px 0 0;
                color: var(--fm-ink);
                font-weight: 600;
            }

            .fm-enc-tag {
                margin-left: 4px;
                padding: 1px 7px;
                border-radius: 999px;
                background: var(--fm-warning-soft);
                color: var(--fm-warning);
                font-size: 11.5px;
                font-weight: 600;
            }

            @media (max-width: 767.98px) {
                .fm-enc-head {
                    flex-wrap: wrap;
                }

                .fm-enc-grid > div + div {
                    border-left: 0;
                    border-top: 1px solid var(--fm-line);
                }
            }

            /* ---- search results ---- */
            #searchModal .modal-content {
                max-height: min(80vh, 760px);
            }

            #searchModal .modal-body {
                padding-top: 0;
            }

            #searchModal .fm-search-scope {
                position: sticky;
                top: 0;
                z-index: 2;
                margin: 0 -20px 12px;
                padding: 14px 20px 10px;
                background: var(--fm-surface);
                border-bottom: 1px solid var(--fm-line);
            }

            ul#search-wrapper {
                margin: 0;
                padding: 0;
                list-style: none;
            }

            ul#search-wrapper li.fm-result {
                position: relative;
                display: flex;
                align-items: center;
                padding: 0;
                border-bottom: 1px solid var(--fm-line);
            }

            ul#search-wrapper li.fm-result:last-child {
                border-bottom: 0;
            }

            ul#search-wrapper .fm-result-main,
            ul#search-wrapper .fm-result-main:visited {
                display: flex;
                flex: 1;
                align-items: center;
                gap: 12px;
                min-width: 0;
                padding: 9px 12px;
                color: var(--fm-ink);
            }

            ul#search-wrapper .fm-result-main > i {
                flex: 0 0 22px;
                width: 22px;
                font-size: 17px;
                text-align: center;
            }

            ul#search-wrapper .fm-result-main > i.fa-file-o {
                color: var(--fm-muted);
            }

            .fm-result-text {
                display: flex;
                flex-direction: column;
                min-width: 0;
            }

            .fm-result-name {
                overflow: hidden;
                color: var(--fm-ink);
                font-weight: 600;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-result-name mark {
                padding: 0 1px;
                border-radius: 3px;
                background: var(--fm-zip-soft);
                color: inherit;
                box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--fm-ic-zip) 55%, transparent);
            }

            .fm-result-path {
                display: flex;
                align-items: center;
                gap: 6px;
                overflow: hidden;
                color: var(--fm-muted);
                font-size: 12.5px;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-result-path i {
                color: var(--fm-folder);
                font-size: 11px;
            }

            ul#search-wrapper li.fm-result:hover,
            ul#search-wrapper li.fm-result:has(.is-active) {
                background: var(--fm-hover);
            }

            ul#search-wrapper .fm-result-main.is-active {
                box-shadow: inset 3px 0 0 var(--fm-accent);
            }

            ul#search-wrapper .fm-result-main:focus-visible {
                box-shadow: inset 0 0 0 2px var(--fm-accent) !important;
                border-radius: 0;
            }

            ul#search-wrapper .fm-result-folder,
            ul#search-wrapper .fm-result-folder:visited {
                display: inline-flex;
                align-items: center;
                gap: 6px;
                margin-right: 10px;
                padding: 5px 10px;
                border: 1px solid var(--fm-line-strong);
                border-radius: 7px;
                background: var(--fm-surface);
                color: var(--fm-ink);
                font-size: 12.5px;
                font-weight: 500;
                white-space: nowrap;
                opacity: 0;
                transition: opacity .12s;
            }

            ul#search-wrapper .fm-result-folder i {
                color: var(--fm-folder);
            }

            ul#search-wrapper li.fm-result:hover .fm-result-folder,
            ul#search-wrapper li.fm-result:has(.is-active) .fm-result-folder,
            ul#search-wrapper .fm-result-folder:focus-visible {
                opacity: 1;
            }

            ul#search-wrapper .fm-result-folder:hover {
                border-color: var(--fm-accent);
                color: var(--fm-accent);
            }

            ul#search-wrapper li.fm-results-head {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                justify-content: space-between;
                gap: 6px 16px;
                padding: 2px 2px 10px;
                border: 0;
                background: none;
                color: var(--fm-muted);
                font-size: 13px;
            }

            ul#search-wrapper li.fm-results-head strong {
                color: var(--fm-ink);
            }

            .fm-results-keys kbd {
                padding: 1px 6px;
                margin: 0 1px;
                border: 1px solid var(--fm-line-strong);
                border-radius: 5px;
                background: var(--fm-surface);
                color: var(--fm-ink);
                font-family: var(--fm-mono);
                font-size: 11px;
                box-shadow: 0 1px 0 var(--fm-line-strong);
            }

            ul#search-wrapper li.fm-search-partial {
                margin-bottom: 10px;
                border: 1px solid color-mix(in srgb, var(--fm-warning) 35%, transparent);
                border-radius: 8px;
            }

            /* the result rows sit in one bordered list, below the head and any notice */
            ul#search-wrapper:has(li.fm-result) {
                border: 0;
            }

            ul#search-wrapper li.fm-result:first-of-type,
            ul#search-wrapper li.fm-results-head + li.fm-result,
            ul#search-wrapper li.fm-search-partial + li.fm-result {
                border-top: 1px solid var(--fm-line);
                border-top-left-radius: 10px;
                border-top-right-radius: 10px;
            }

            ul#search-wrapper li.fm-result {
                border-left: 1px solid var(--fm-line);
                border-right: 1px solid var(--fm-line);
            }

            ul#search-wrapper li.fm-result:last-child {
                border-bottom: 1px solid var(--fm-line);
                border-bottom-left-radius: 10px;
                border-bottom-right-radius: 10px;
            }

            @media (hover: none) {
                ul#search-wrapper .fm-result-folder {
                    opacity: 1;
                }
            }

            @media (max-width: 575.98px) {
                ul#search-wrapper .fm-result-folder span,
                .fm-results-keys {
                    display: none;
                }
            }

            /* ---- search dialog header, field and empty state (same pattern as the other dialogs) ---- */
            .fm-search-title i {
                color: var(--fm-accent);
                margin-right: 4px;
            }

            #searchModal .fm-search-scope .fm-search-field {
                flex: 1 1 100%;
                margin-bottom: 4px;
            }

            #searchModal .fm-search-scope {
                padding-top: 16px;
            }

            ul#search-wrapper > p:only-child {
                padding: 36px 12px 32px;
            }

            ul#search-wrapper > p:only-child::before {
                font-size: 30px;
                color: var(--fm-line-strong);
                margin-bottom: 4px;
            }

            /* ---- styled select dropdown ---- */
            .fm-select-native {
                position: absolute !important;
                width: 1px !important;
                height: 1px !important;
                opacity: 0;
                pointer-events: none;
            }

            .fm-select {
                flex: 0 0 220px;
                width: 220px;
            }

            .fm-select-toggle {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 10px;
                width: 100%;
                height: 38px;
                padding: 0 12px;
                border: 1px solid var(--fm-line-strong);
                border-radius: 8px;
                background: var(--fm-surface);
                color: var(--fm-ink);
                font-size: 14px;
                font-weight: 500;
                text-align: left;
                transition: border-color .15s, box-shadow .15s;
            }

            .fm-select-toggle span {
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-select-toggle i {
                color: var(--fm-muted);
                transition: transform .15s;
            }

            .fm-select-toggle:hover {
                border-color: var(--fm-accent);
            }

            .fm-select-toggle[aria-expanded="true"] {
                border-color: var(--fm-accent);
                box-shadow: var(--fm-focus);
            }

            .fm-select-toggle[aria-expanded="true"] i {
                transform: rotate(180deg);
            }

            .fm-select-menu {
                width: 100%;
                min-width: 220px;
                max-height: 320px;
                overflow-y: auto;
                margin-top: 6px !important;
                padding: 6px;
            }

            .fm-select-item {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 10px;
                padding: 8px 10px;
                border-radius: 6px;
                font-size: 14px;
            }

            .fm-select-item i {
                color: var(--fm-accent);
                visibility: hidden;
            }

            .fm-select-item.is-selected {
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-weight: 600;
            }

            .fm-select-item.is-selected i {
                visibility: visible;
            }

            .fm-select-item:focus-visible {
                box-shadow: inset 0 0 0 2px var(--fm-accent) !important;
            }

            .fm-select-filter {
                position: relative;
                margin-bottom: 6px;
            }

            .fm-select-filter i {
                position: absolute;
                top: 50%;
                left: 10px;
                transform: translateY(-50%);
                color: var(--fm-muted);
                font-size: 12px;
            }

            .fm-select-filter .form-control {
                padding-left: 28px;
            }

            .fm-select-note {
                display: flex;
                align-items: flex-start;
                gap: 8px;
                margin-top: 6px;
                padding: 8px 10px 4px;
                border-top: 1px solid var(--fm-line);
                color: var(--fm-muted);
                font-size: 12.5px;
                line-height: 1.45;
                white-space: normal;
            }

            .fm-select-note i {
                margin-top: 2px;
                color: var(--fm-accent);
            }

            .fm-settings .fm-select-menu {
                min-width: 280px;
            }

            @media (max-width: 767.98px) {
                .fm-select {
                    flex-basis: 100%;
                    width: 100%;
                }
            }

            /* ---- styled dropdowns inside the editor toolbar and encoding notice ---- */
            .fm-editor-select {
                display: inline-flex;
                align-items: center;
                gap: 6px;
            }

            .fm-editor-select > label {
                margin: 0;
                color: var(--fm-muted);
                font-size: 12.5px;
                font-weight: 500;
                cursor: pointer;
            }

            .fm-editor-select .fm-select {
                flex: none;
                width: auto;
                min-width: 120px;
            }

            .fm-editor-select .fm-select-toggle {
                height: 32px;
                padding: 0 10px;
                font-size: 13px;
            }

            .fm-editor-select #js-ace-fontSize-button {
                min-width: 70px;
            }

            .fm-editor-select .fm-select-menu {
                min-width: 220px;
                max-height: 360px;
            }

            .fm-select-group {
                position: sticky;
                top: -6px;
                z-index: 1;
                margin: 6px -6px 2px;
                padding: 6px 16px 4px;
                background: var(--fm-surface);
                color: var(--fm-muted);
                font-size: 11.5px;
                font-weight: 600;
            }

            .fm-select-filter {
                position: sticky;
                top: -6px;
                z-index: 2;
                margin: -6px -6px 6px;
                padding: 6px;
                background: var(--fm-surface);
                border-bottom: 1px solid var(--fm-line);
            }

            .fm-select-filter i {
                left: 16px;
            }

            /* group headings stick just below the filter box */
            .fm-select-filter ~ .fm-select-group {
                top: 39px;
            }

            /* ---- account menu ---- */
            .fm-account-toggle i.fa-angle-down {
                color: var(--fm-muted);
                transition: transform .15s;
            }

            .fm-account-toggle[aria-expanded="true"] i.fa-angle-down {
                transform: rotate(180deg);
            }

            .fm-topbar .fm-account-toggle:focus:not(:focus-visible) {
                box-shadow: none !important;
            }

            .fm-topbar .fm-account-menu {
                width: 290px;
                margin-top: 8px !important;
                padding: 0;
                overflow: hidden;
            }

            .fm-account-head {
                display: flex;
                align-items: center;
                gap: 12px;
                padding: 16px;
                border-bottom: 1px solid var(--fm-line);
                background: var(--fm-tier);
            }

            .fm-avatar-lg {
                flex: 0 0 44px;
                width: 44px;
                height: 44px;
                font-size: 18px;
            }

            .fm-account-who {
                display: flex;
                flex-direction: column;
                align-items: flex-start;
                gap: 4px;
                min-width: 0;
            }

            .fm-account-who strong {
                max-width: 100%;
                overflow: hidden;
                color: var(--fm-ink);
                font-size: 15px;
                font-weight: 650;
                text-overflow: ellipsis;
                white-space: nowrap;
                text-transform: none;
            }

            .fm-access-badge {
                display: inline-flex;
                align-items: center;
                gap: 5px;
                padding: 1px 8px;
                border-radius: 999px;
                background: var(--fm-success-soft);
                color: var(--fm-success);
                font-size: 11.5px;
                font-weight: 600;
            }

            .fm-access-badge.is-readonly {
                background: var(--fm-warning-soft);
                color: var(--fm-warning);
            }

            .fm-account-root {
                display: inline-flex;
                align-items: center;
                gap: 6px;
                max-width: 100%;
                overflow: hidden;
                color: var(--fm-muted);
                font-family: var(--fm-mono);
                font-size: 12px;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-account-root i {
                color: var(--fm-folder);
            }

            .fm-account-items {
                padding: 6px;
            }

            .fm-topbar .fm-account-item {
                display: flex;
                align-items: center;
                gap: 12px;
                padding: 8px 10px;
                border-radius: 8px;
                white-space: normal;
            }

            .fm-account-item > span:last-child {
                display: flex;
                flex-direction: column;
                line-height: 1.35;
            }

            .fm-account-item strong {
                font-weight: 600;
            }

            .fm-account-item small {
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-account-icon {
                display: grid;
                place-items: center;
                flex: 0 0 32px;
                width: 32px;
                height: 32px;
                border-radius: 8px;
                font-size: 14px;
            }

            .fm-topbar .fm-account-icon i.fa {
                width: auto;
                color: inherit !important;
                opacity: 1;
            }

            .fm-account-icon.is-settings {
                background: var(--fm-hover);
                color: var(--fm-ic-neutral);
            }

            .fm-account-icon.is-help {
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
            }

            .fm-account-icon.is-password {
                background: var(--fm-hover);
                color: var(--fm-ic-neutral);
            }

            /* ---- Settings page: side tabs + rows ---- */
            .fm-set-page .fm-page-head {
                margin-bottom: 14px;
            }

            .fm-set.card {
                display: grid;
                grid-template-columns: 216px minmax(0, 1fr);
                grid-template-rows: minmax(0, 1fr) auto;
                overflow: visible; /* lets the save bar stick to the bottom of the window */
            }

            .fm-set-nav {
                display: flex;
                flex-direction: column;
                gap: 10px;
                padding: 14px 12px;
                border-right: 1px solid var(--fm-line);
                border-radius: 12px 0 0 0;
                background: var(--fm-tier);
            }

            .fm-set-search {
                position: relative;
            }

            .fm-set-search i {
                position: absolute;
                top: 50%;
                left: 11px;
                transform: translateY(-50%);
                color: var(--fm-muted);
                font-size: 13px;
                pointer-events: none;
            }

            .fm-set-search input {
                width: 100%;
                height: 34px;
                padding: 0 10px 0 31px;
                border: 1px solid var(--fm-line);
                border-radius: 8px;
                background: var(--fm-surface);
                color: var(--fm-ink);
                font-size: 13px;
            }

            .fm-set-search input:focus {
                outline: 0;
                border-color: var(--fm-accent);
                box-shadow: var(--fm-focus);
            }

            .fm-set-tabs {
                display: flex;
                flex-direction: column;
                gap: 2px;
            }

            .fm-set-tab {
                display: flex;
                align-items: center;
                gap: 10px;
                width: 100%;
                padding: 8px 10px;
                border: 0;
                border-radius: 8px;
                background: transparent;
                color: var(--fm-muted);
                font-size: 13.5px;
                text-align: left;
                white-space: nowrap;
                transition: background-color .15s, color .15s;
            }

            .fm-set-tab i.fa {
                width: 16px;
                text-align: center;
            }

            .fm-set-tab:hover {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            .fm-set-tab.is-active {
                background: var(--fm-surface);
                color: var(--fm-accent);
                font-weight: 600;
                box-shadow: var(--fm-shadow);
            }

            [data-bs-theme=dark] .fm-set-tab.is-active {
                background: var(--fm-hover);
                box-shadow: inset 0 0 0 1px var(--fm-line-strong);
            }

            .fm-set-tab:focus-visible {
                outline: 0;
                box-shadow: var(--fm-focus);
            }

            .fm-set-nav-note {
                display: flex;
                gap: 7px;
                margin: auto 0 0;
                padding: 10px 4px 0;
                border-top: 1px solid var(--fm-line);
                color: var(--fm-muted);
                font-size: 11.5px;
                line-height: 1.45;
            }

            .fm-set-nav-note i {
                margin-top: 2px;
            }

            .fm-set-nav-note code {
                color: var(--fm-ink);
                font-size: 11px;
            }

            .fm-set-tab-dot {
                width: 7px;
                height: 7px;
                margin-left: auto;
                border-radius: 50%;
                background: var(--fm-warning);
            }

            .fm-set-tab-dot[hidden] {
                display: none;
            }

            .fm-set-main {
                min-width: 0;
                padding: 2px 24px 10px;
            }

            .fm-set-panel-head {
                display: flex;
                flex-wrap: wrap;
                align-items: baseline;
                gap: 2px 12px;
                padding: 14px 0 10px;
                border-bottom: 1px solid var(--fm-line);
            }

            .fm-set-panel-head h2 {
                display: flex;
                align-items: center;
                gap: 9px;
                margin: 0;
                font-size: 16px;
                font-weight: 650;
            }

            .fm-set-panel-head h2 i {
                color: var(--fm-accent);
                font-size: 15px;
            }

            .fm-set-panel-head p {
                margin: 0;
                color: var(--fm-muted);
                font-size: 13px;
            }

            /* searching shows matches from every tab, one heading per tab */
            .fm-set.is-searching .fm-set-panel + .fm-set-panel .fm-set-panel-head {
                margin-top: 8px;
            }

            .fm-set-note {
                display: flex;
                align-items: flex-start;
                gap: 9px;
                margin: 10px 0 2px;
                padding: 8px 12px;
                border-radius: 8px;
                background: var(--fm-tier);
                color: var(--fm-muted);
                font-size: 12.5px;
                line-height: 1.45;
            }

            .fm-set-note i {
                margin-top: 2px;
            }

            .fm-set-note.is-warn {
                background: var(--fm-warning-soft);
                color: var(--fm-warning);
            }

            .fm-set-note b {
                color: var(--fm-ink);
                font-family: var(--fm-mono);
            }

            .fm-set-row {
                display: grid;
                grid-template-columns: minmax(0, 1fr) minmax(200px, 270px) 28px;
                align-items: center;
                gap: 6px 16px;
                padding: 8px 0;
                border-bottom: 1px dashed var(--fm-line);
            }

            .fm-set-row:last-child {
                border-bottom: 0;
            }

            .fm-set-row[hidden] {
                display: none;
            }

            .fm-set-text {
                min-width: 0;
            }

            .fm-set-label {
                display: inline-flex;
                align-items: center;
                gap: 7px;
                margin: 0;
                color: var(--fm-ink);
                font-size: 13.5px;
                font-weight: 600;
            }

            .fm-set-row.is-danger .fm-set-label i {
                color: var(--fm-danger);
                font-size: 12px;
            }

            /* changed from the default: accent dot; changed but not saved yet: "unsaved" tag */
            .fm-set-row.is-modified .fm-set-label::after {
                content: "";
                width: 7px;
                height: 7px;
                border-radius: 50%;
                background: var(--fm-accent);
            }

            .fm-set-row.is-dirty .fm-set-label::after {
                content: "unsaved";
                width: auto;
                height: auto;
                padding: 0 7px;
                border-radius: 10px;
                background: var(--fm-warning-soft);
                color: var(--fm-warning);
                font-size: 11px;
                font-weight: 600;
                line-height: 18px;
            }

            .fm-set-desc {
                margin: 2px 0 0;
                color: var(--fm-muted);
                font-size: 12.5px;
                line-height: 1.45;
            }

            .fm-set-desc code,
            .fm-set-danger code,
            .fm-set-note code {
                padding: 0 4px;
                border-radius: 4px;
                background: var(--fm-hover);
                color: var(--fm-ink);
                font-size: 11.5px;
            }

            .fm-set-default {
                white-space: nowrap;
                opacity: .8;
            }

            .fm-set-default::before {
                content: "·";
                margin-right: 5px;
            }

            .fm-set-danger {
                margin: 3px 0 0;
                color: var(--fm-danger);
                font-size: 12px;
            }

            .fm-set-error {
                margin: 4px 0 0;
                color: var(--fm-danger);
                font-size: 12.5px;
                font-weight: 600;
            }

            .fm-set-error[hidden],
            .fm-set-confirm[hidden] {
                display: none;
            }

            .fm-set-confirm {
                display: flex;
                align-items: flex-start;
                gap: 8px;
                margin: 6px 0 0;
                padding: 7px 10px;
                border-radius: 8px;
                background: var(--fm-danger-soft);
                color: var(--fm-danger);
                font-size: 12.5px;
                font-weight: 600;
                cursor: pointer;
            }

            .fm-set-confirm .form-check-input {
                flex: none;
                margin: 2px 0 0;
            }

            .fm-set-control {
                display: flex;
                flex-direction: column;
                gap: 4px;
                min-width: 0;
            }

            .fm-set-control.is-inline {
                flex-direction: row;
                justify-content: flex-end;
            }

            .fm-set-control .fm-select {
                flex: none; /* the shared style sets a 220px flex-basis meant for rows */
                width: 100%;
            }

            .fm-set .fm-select-menu {
                min-width: 100%;
                max-height: 320px;
                overflow-y: auto;
            }

            .fm-set-control .form-control,
            .fm-set-control .fm-select-toggle {
                height: 34px;
                font-size: 13.5px;
            }

            .fm-set-control textarea.fm-set-lines {
                height: auto;
                min-height: 54px;
                padding: 6px 10px;
                font-family: var(--fm-mono);
                font-size: 12.5px;
                line-height: 1.55;
                resize: vertical;
            }

            .fm-set-control .fm-segmented label {
                padding: 4px 13px;
            }

            .fm-set-control .form-control::placeholder,
            .fm-user .form-control::placeholder,
            .fm-user-add .form-control::placeholder {
                color: var(--fm-muted);
                opacity: .7;
            }

            .fm-set-warn {
                margin: 4px 0 0;
                color: var(--fm-warning);
                font-size: 12.5px;
                font-weight: 600;
            }

            .fm-set-warn[hidden] {
                display: none;
            }

            .fm-set-row.has-error .form-control,
            .fm-set-row.has-error .fm-select-toggle {
                border-color: var(--fm-danger);
            }

            .fm-set-bytes .input-group-text {
                font-size: 12.5px;
            }

            .fm-set-preview {
                color: var(--fm-muted);
                font-family: var(--fm-mono);
                font-size: 12px;
            }

            .fm-set-reset {
                display: grid;
                place-items: center;
                width: 28px;
                height: 28px;
                border: 0;
                border-radius: 7px;
                background: transparent;
                color: var(--fm-muted);
                visibility: hidden;
            }

            .fm-set-row.is-modified .fm-set-reset {
                visibility: visible;
            }

            .fm-set-reset:hover {
                background: var(--fm-hover);
                color: var(--fm-accent);
            }

            .fm-set-reset:focus-visible {
                outline: 0;
                box-shadow: var(--fm-focus);
            }

            .fm-set-empty {
                padding: 40px 0;
                color: var(--fm-muted);
                text-align: center;
            }

            .fm-set-empty[hidden] {
                display: none;
            }

            .fm-set-bar {
                grid-column: 1 / -1;
                position: sticky;
                bottom: 0;
                z-index: 5;
                display: flex;
                align-items: center;
                justify-content: flex-end;
                gap: 10px;
                padding: 10px 16px;
                border-top: 1px solid var(--fm-line);
                border-radius: 0 0 12px 12px;
                background: color-mix(in srgb, var(--fm-surface) 92%, transparent);
                backdrop-filter: blur(6px);
            }

            .fm-set-status {
                margin-right: auto;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-set-status i {
                margin-right: 4px;
            }

            .fm-set-status.is-dirty {
                color: var(--fm-warning);
                font-weight: 600;
            }

            .fm-set-status.is-dirty i {
                font-size: 8px;
                vertical-align: 2px;
            }

            .fm-set-status.is-clean i {
                color: var(--fm-success);
            }

            .fm-set-status.is-error {
                color: var(--fm-danger);
                font-weight: 600;
            }

            /* users tab */
            .fm-users {
                display: flex;
                flex-direction: column;
            }

            .fm-user {
                display: grid;
                grid-template-columns: 32px minmax(110px, 1fr) auto minmax(160px, 1.2fr) auto;
                align-items: center;
                gap: 8px 14px;
                padding: 10px 0;
                border-bottom: 1px dashed var(--fm-line);
            }

            .fm-user .fm-avatar {
                width: 32px;
                height: 32px;
            }

            .fm-user-name {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 6px;
                min-width: 0;
            }

            .fm-user-name strong {
                overflow: hidden;
                font-size: 14px;
                text-overflow: ellipsis;
            }

            .fm-user-tag {
                padding: 0 7px;
                border-radius: 10px;
                font-size: 11px;
                font-weight: 600;
                line-height: 18px;
            }

            .fm-user-tag.is-you {
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
            }

            .fm-user-tag.is-new {
                background: var(--fm-warning-soft);
                color: var(--fm-warning);
            }

            .fm-user .fm-segmented label {
                padding: 4px 11px;
                font-size: 12.5px;
            }

            .fm-user .fm-segmented input:disabled + label {
                opacity: .45;
                cursor: not-allowed;
            }

            .fm-user .fm-input-icon,
            .fm-user-add .fm-input-icon {
                flex: none;
            }

            .fm-user .fm-input-icon .form-control,
            .fm-user-add .fm-input-icon .form-control {
                height: 34px;
                font-size: 13px;
            }

            .fm-user-pwd-field .form-control {
                padding-right: 38px;
                font-family: var(--fm-mono);
                font-size: 13.5px !important;
            }

            .fm-user-actions {
                display: flex;
                gap: 2px;
            }

            .fm-user-btn {
                display: grid;
                place-items: center;
                width: 32px;
                height: 32px;
                border: 0;
                border-radius: 8px;
                background: transparent;
                color: var(--fm-muted);
            }

            .fm-user-btn:hover:not(:disabled) {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            .fm-user-btn.is-danger:hover:not(:disabled) {
                background: var(--fm-danger-soft);
                color: var(--fm-danger);
            }

            .fm-user-btn:disabled {
                opacity: .35;
                cursor: not-allowed;
            }

            .fm-user-pwd {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 6px 12px;
                grid-column: 2 / -1;
            }

            .fm-user-pwd .fm-input-icon {
                flex: 1 1 260px;
            }

            .fm-user-pwd-hint {
                color: var(--fm-muted);
                font-size: 12px;
            }

            .fm-user-add {
                display: grid;
                grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr) auto;
                gap: 10px;
                margin-top: 12px;
                padding: 12px;
                border: 1px dashed var(--fm-line-strong);
                border-radius: 10px;
            }

            #fm-users-error {
                margin-top: 8px;
            }

            @media (max-width: 860px) {
                .fm-set.card {
                    grid-template-columns: minmax(0, 1fr);
                }

                .fm-set-nav {
                    border-right: 0;
                    border-bottom: 1px solid var(--fm-line);
                    border-radius: 12px 12px 0 0;
                }

                .fm-set-tabs {
                    flex-direction: row;
                    overflow-x: auto;
                    scrollbar-width: none;
                }

                .fm-set-tab {
                    width: auto;
                }

                .fm-set-nav-note {
                    display: none;
                }

                .fm-set-main {
                    padding: 2px 16px 10px;
                }

                .fm-set-row {
                    grid-template-columns: minmax(0, 1fr) 28px;
                }

                .fm-set-control {
                    grid-column: 1;
                    grid-row: 2;
                }

                .fm-set-control.is-inline {
                    justify-content: flex-start;
                }

                .fm-set-reset {
                    grid-column: 2;
                    grid-row: 1;
                }

                .fm-user {
                    grid-template-columns: 32px minmax(0, 1fr) auto;
                }

                .fm-user .fm-user-access,
                .fm-user .fm-user-dir {
                    grid-column: 2 / -1;
                }

                .fm-user .fm-user-actions {
                    grid-column: 3;
                    grid-row: 1;
                }

                .fm-user-add {
                    grid-template-columns: minmax(0, 1fr);
                }

                .fm-set-bar {
                    padding: 10px 12px;
                }

                .fm-set-bar .btn {
                    white-space: nowrap;
                }

                .fm-set-status {
                    font-size: 12px;
                }
            }

            /* ---- Settings: file/folder buttons, chip rows, the shared modal ---- */
            .fm-set-pick {
                display: flex;
                align-items: stretch;
                min-width: 0;
                height: 34px;
                border: 1px solid var(--fm-line-strong);
                border-radius: 8px;
                background: var(--fm-surface);
                transition: border-color .15s, box-shadow .15s;
            }

            .fm-set-pick:hover {
                border-color: var(--fm-accent);
            }

            .fm-set-pick:focus-within {
                border-color: var(--fm-accent);
                box-shadow: var(--fm-focus);
            }

            .fm-set-row.has-error .fm-set-pick {
                border-color: var(--fm-danger);
            }

            .fm-set-pick-btn {
                display: flex;
                flex: 1;
                align-items: center;
                gap: 9px;
                min-width: 0;
                padding: 0 10px 0 6px;
                border: 0;
                border-radius: 8px;
                background: transparent;
                color: var(--fm-ink);
                font-size: 13px;
                text-align: left;
            }

            .fm-set-pick-btn:focus-visible {
                outline: 0;
            }

            .fm-set-pick-thumb {
                display: grid;
                flex: none;
                place-items: center;
                width: 26px;
                height: 24px;
                overflow: hidden;
                border-radius: 5px;
                background: var(--fm-tier);
                color: var(--fm-folder);
                font-size: 13px;
            }

            .fm-set-pick[data-pick="image"] .fm-set-pick-thumb {
                width: 44px;
                padding: 2px;
                background: repeating-conic-gradient(var(--fm-hover) 0 25%, var(--fm-surface) 0 50%) 0 0 / 8px 8px;
                color: var(--fm-muted);
            }

            #fm-s-logo_dark_path .fm-set-pick-thumb {
                background: #1B1E27; /* the dark-theme logo is light: show it on dark */
            }

            .fm-set-pick-thumb img {
                max-width: 100%;
                max-height: 100%;
                object-fit: contain;
            }

            .fm-set-pick-text {
                flex: 1;
                min-width: 0;
                overflow: hidden;
                direction: rtl; /* long paths keep their end visible */
                font-family: var(--fm-mono);
                font-size: 12.5px;
                text-align: left;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-set-pick-text.is-empty {
                direction: ltr;
                color: var(--fm-muted);
                font-family: inherit;
                font-size: 13px;
            }

            .fm-set-pick-go {
                color: var(--fm-accent);
            }

            .fm-set-pick-clear {
                flex: none;
                width: 30px;
                border: 0;
                border-left: 1px solid var(--fm-line);
                border-radius: 0 8px 8px 0;
                background: transparent;
                color: var(--fm-muted);
            }

            .fm-set-pick-clear:hover {
                background: var(--fm-danger-soft);
                color: var(--fm-danger);
            }

            .fm-set-pick-clear[hidden] {
                display: none;
            }

            .fm-set-chipbox {
                display: flex;
                align-items: center;
                gap: 8px;
                min-width: 0;
            }

            .fm-set-chips {
                display: flex;
                flex: 1;
                flex-wrap: nowrap;
                gap: 4px;
                min-width: 0;
                overflow: hidden;
            }

            .fm-set-chips-empty {
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-set-edit {
                flex: none;
                height: 30px;
                font-size: 12.5px;
            }

            .fm-chip {
                display: inline-flex;
                flex: none;
                align-items: center;
                max-width: 150px;
                padding: 1px 8px;
                overflow: hidden;
                border: 1px solid var(--fm-line);
                border-radius: 12px;
                background: var(--fm-tier);
                color: var(--fm-ink);
                font-size: 12px;
                line-height: 20px;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-chip.is-mono {
                font-family: var(--fm-mono);
                font-size: 11.5px;
            }

            .fm-chip.is-more {
                border-color: transparent;
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-weight: 600;
            }

            .fm-set-custom {
                margin-top: 2px;
                font-family: var(--fm-mono);
            }

            .fm-set-custom[hidden],
            .fm-set-preview[hidden] {
                display: none;
            }

            /* modal */
            .fm-sm-dialog .modal-body {
                min-height: 220px;
                max-height: min(62vh, 520px);
                overflow-y: auto;
            }

            .fm-sm-dialog .modal-title i {
                margin-right: 6px;
                color: var(--fm-accent);
            }

            .fm-sm-note {
                margin-right: auto;
                overflow: hidden;
                color: var(--fm-muted);
                font-family: var(--fm-mono);
                font-size: 12px;
                text-overflow: ellipsis;
                white-space: nowrap;
                max-width: 55%;
            }

            .fm-sm-pathbar {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                justify-content: space-between;
                gap: 8px 12px;
                margin-bottom: 10px;
            }

            .fm-sm-crumbs {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 1px;
                min-width: 0;
                color: var(--fm-muted);
                font-family: var(--fm-mono);
                font-size: 12.5px;
            }

            .fm-sm-crumb {
                padding: 2px 5px;
                border: 0;
                border-radius: 5px;
                background: transparent;
                color: var(--fm-ink);
            }

            .fm-sm-crumb:hover {
                background: var(--fm-hover);
                color: var(--fm-accent);
            }

            .fm-sm-go {
                display: flex;
                flex: 0 1 300px;
                gap: 6px;
            }

            .fm-sm-go input {
                font-family: var(--fm-mono);
                font-size: 12.5px;
            }

            .fm-sm-split {
                display: flex;
                gap: 12px;
            }

            .fm-sm-list {
                display: flex;
                flex: 1;
                flex-direction: column;
                min-width: 0;
                max-height: 330px;
                padding: 4px;
                overflow-y: auto;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
            }

            .fm-sm-item {
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 6px 9px;
                border: 0;
                border-radius: 7px;
                background: transparent;
                color: var(--fm-ink);
                font-size: 13.5px;
                text-align: left;
            }

            .fm-sm-item span:not(.fm-sm-file-ic) {
                flex: 1;
                min-width: 0;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-sm-item:hover {
                background: var(--fm-hover);
            }

            .fm-sm-item.is-dir > i.fa-folder {
                color: var(--fm-folder);
            }

            .fm-sm-item.is-up {
                color: var(--fm-muted);
            }

            .fm-sm-go-in {
                color: var(--fm-muted);
                opacity: 0;
            }

            .fm-sm-item:hover .fm-sm-go-in {
                opacity: 1;
            }

            .fm-sm-item.is-picked {
                background: var(--fm-accent-soft);
                box-shadow: inset 0 0 0 1px var(--fm-accent);
            }

            .fm-sm-file-ic {
                display: grid;
                flex: none;
                place-items: center;
                width: 28px;
                height: 22px;
                color: var(--fm-muted);
            }

            .fm-sm-file-ic img {
                max-width: 100%;
                max-height: 100%;
                object-fit: contain;
            }

            .fm-sm-preview {
                display: flex;
                flex: 0 0 180px;
                flex-direction: column;
                align-items: center;
                gap: 8px;
                color: var(--fm-muted);
                font-size: 12.5px;
                text-align: center;
                overflow-wrap: anywhere;
            }

            .fm-sm-preview-img {
                display: grid;
                place-items: center;
                width: 180px;
                height: 120px;
                padding: 10px;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                background: repeating-conic-gradient(var(--fm-hover) 0 25%, var(--fm-surface) 0 50%) 0 0 / 14px 14px;
                font-size: 28px;
            }

            .fm-sm-preview-img img {
                max-width: 100%;
                max-height: 100%;
                object-fit: contain;
            }

            .fm-sm-loading,
            .fm-sm-empty {
                margin: 0;
                padding: 18px 10px;
                color: var(--fm-muted);
                font-size: 13px;
                text-align: center;
            }

            .fm-sm-error {
                margin-top: 8px;
            }

            .fm-sm-add {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 8px;
            }

            .fm-sm-add .fm-input-icon {
                flex: 1 1 240px;
            }

            .fm-sm-add .fm-input-icon .form-control {
                height: 38px;
                font-family: var(--fm-mono);
                font-size: 13.5px;
            }

            .fm-sm-add .form-select {
                flex: 0 0 170px;
                height: 38px;
            }

            .fm-sm-arrow {
                color: var(--fm-muted);
            }

            .fm-sm-hint {
                margin: 6px 0 10px;
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-sm-hint.is-bad {
                color: var(--fm-danger);
                font-weight: 600;
            }

            .fm-sm-hint.is-warn {
                color: var(--fm-warning);
                font-weight: 600;
            }

            .fm-sm-suggest {
                margin-left: 4px;
                padding: 1px 9px;
                border: 1px solid currentColor;
                border-radius: 12px;
                background: var(--fm-warning-soft);
                color: var(--fm-warning);
                font-size: 12px;
                font-weight: 600;
            }

            .fm-sm-suggest:hover {
                background: var(--fm-warning);
                color: var(--fm-surface);
            }

            .fm-sm-hint.is-good {
                color: var(--fm-success);
                font-weight: 600;
            }

            .fm-sm-mine {
                padding: 0;
                text-decoration: none;
            }

            .fm-sm-rows {
                display: flex;
                flex-direction: column;
                gap: 6px;
            }

            .fm-sm-row {
                display: flex;
                align-items: center;
                gap: 8px;
            }

            .fm-sm-row .form-control {
                flex: 1;
                font-family: var(--fm-mono);
                font-size: 13px;
            }

            .fm-sm-row .form-control.is-invalid {
                border-color: var(--fm-danger);
                background-image: none;
            }

            .fm-sm-map-row .form-control {
                flex: 0 0 140px;
            }

            .fm-sm-map-row .form-select {
                flex: 1;
            }

            .fm-sm-badge {
                flex: 0 0 auto;
                min-width: 64px;
                padding: 1px 8px;
                border-radius: 10px;
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-size: 11.5px;
                font-weight: 600;
                text-align: center;
            }

            .fm-sm-badge.is-bad {
                background: var(--fm-danger-soft);
                color: var(--fm-danger);
            }

            .fm-sm-groups {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 6px;
                margin-bottom: 12px;
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-sm-group {
                padding: 3px 10px;
                border: 1px dashed var(--fm-line-strong);
                border-radius: 14px;
                background: transparent;
                color: var(--fm-ink);
                font-size: 12.5px;
            }

            .fm-sm-group:hover {
                border-color: var(--fm-accent);
                color: var(--fm-accent);
            }

            .fm-sm-chips {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 6px;
                min-height: 40px;
                padding: 10px;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                background: var(--fm-tier);
            }

            .fm-chip.is-edit {
                max-width: none;
                padding: 0 2px 0 0;
                background: var(--fm-surface);
            }

            .fm-chip-text,
            .fm-chip-x {
                border: 0;
                background: transparent;
                color: inherit;
            }

            .fm-chip-text {
                padding: 2px 4px 2px 9px;
                font: inherit;
            }

            .fm-chip-x {
                padding: 0 6px;
                border-radius: 10px;
                color: var(--fm-muted);
            }

            .fm-chip-x:hover {
                background: var(--fm-danger-soft);
                color: var(--fm-danger);
            }

            .fm-sm-clear {
                margin-left: auto;
                padding: 0 4px;
                color: var(--fm-danger);
                text-decoration: none;
            }

            .fm-sm-anynote {
                margin: 8px 0 0;
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-user-add {
                grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr) minmax(0, 1fr) auto;
            }

            @media (max-width: 860px) {
                .fm-sm-split {
                    flex-direction: column;
                }

                .fm-sm-preview {
                    flex-direction: row;
                    flex-basis: auto;
                }

                .fm-sm-preview-img {
                    width: 120px;
                    height: 80px;
                }

                .fm-sm-go {
                    flex-basis: 100%;
                }

                .fm-user-add {
                    grid-template-columns: minmax(0, 1fr);
                }
            }

            /* ---- Environment page ---- */
            .fm-env-page {
                margin-bottom: 14px;
            }

            .fm-env-page .fm-page-head {
                align-items: center;
                margin-bottom: 12px;
            }

            .fm-env-head-actions {
                display: flex;
                align-items: center;
                gap: 10px;
                font-size: 12.5px;
            }

            .fm-env.card {
                grid-template-rows: minmax(0, 1fr);
            }

            .fm-env .fm-set-nav {
                border-radius: 12px 0 0 12px;
            }

            /* the page itself never scrolls: the panel does */
            .fm-env-main {
                height: calc(100vh - 186px);
                min-height: 420px;
                overflow-y: auto;
                padding-bottom: 16px;
            }

            .fm-env-muted {
                color: var(--fm-muted);
                font-weight: 400;
            }

            .fm-env-note {
                margin: 8px 0 0;
                font-size: 12.5px;
            }

            .fm-env-tab-dot {
                width: 7px;
                height: 7px;
                margin-left: auto;
                border-radius: 50%;
                background: var(--fm-warning);
            }

            .fm-env-tab-dot.is-bad {
                background: var(--fm-danger);
            }

            .fm-env-tab-dot[hidden] {
                display: none;
            }

            /* overview */
            .fm-env-alerts {
                display: flex;
                flex-wrap: wrap;
                gap: 6px 8px;
                padding: 12px 0 10px;
            }

            .fm-env-alert {
                display: inline-flex;
                align-items: center;
                gap: 7px;
                padding: 5px 11px;
                border: 1px solid transparent;
                border-radius: 16px;
                font-size: 12.5px;
                font-weight: 600;
                text-align: left;
            }

            .fm-env-alert[hidden] {
                display: none;
            }

            button.fm-env-alert:hover {
                filter: brightness(.96);
                text-decoration: underline;
            }

            .fm-env-alert.is-bad { background: var(--fm-danger-soft); color: var(--fm-danger); }
            .fm-env-alert.is-warn { background: var(--fm-warning-soft); color: var(--fm-warning); }
            .fm-env-alert.is-ok { background: var(--fm-success-soft); color: var(--fm-success); }
            .fm-env-alert.is-pending { background: var(--fm-tier); color: var(--fm-muted); font-weight: 500; }

            .fm-env-cards {
                display: grid;
                grid-template-columns: repeat(3, minmax(0, 1fr));
                gap: 12px;
            }

            .fm-env-card {
                min-width: 0;
                padding: 10px 14px;
                border: 1px solid var(--fm-line);
                border-radius: 12px;
                background: var(--fm-surface);
            }

            .fm-env-card h3,
            .fm-env-box h3 {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 8px;
                margin: 0 0 8px;
                color: var(--fm-ink);
                font-size: 13.5px;
                font-weight: 650;
            }

            .fm-env-card h3 i,
            .fm-env-box h3 > i {
                color: var(--fm-accent);
            }

            .fm-env-card p {
                margin: 0 0 3px;
                font-size: 13px;
            }

            .fm-env-big {
                font-size: 16px !important;
                font-weight: 650;
            }

            .fm-env-clip {
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-env-gauge {
                display: flex;
                align-items: baseline;
                justify-content: space-between;
                gap: 10px;
                margin: 5px 0 3px;
                font-size: 12.5px;
            }

            .fm-env-gauge span {
                color: var(--fm-muted);
            }

            .fm-env-gauge strong {
                font-size: 13.5px;
            }

            .fm-env-gauge small {
                color: var(--fm-muted);
                font-weight: 400;
            }

            .fm-env-meter {
                height: 7px;
                margin-bottom: 4px;
                overflow: hidden;
                border-radius: 4px;
                background: var(--fm-hover);
            }

            .fm-env-meter span {
                display: block;
                height: 100%;
                border-radius: 4px;
                background: var(--fm-accent);
            }

            .fm-env-meter.is-warn span { background: var(--fm-warning); }
            .fm-env-meter.is-bad span { background: var(--fm-danger); }

            .fm-env-health {
                display: flex;
                flex-direction: column;
                gap: 4px;
                margin: 0;
                padding: 0;
                list-style: none;
                font-size: 13px;
            }

            .fm-env-health li {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 10px;
            }

            .fm-env-health li > span:first-child {
                color: var(--fm-muted);
            }

            .fm-env-chips {
                display: flex;
                flex-wrap: wrap;
                gap: 6px;
                margin: 0 0 6px;
                padding: 0;
                list-style: none;
            }

            .fm-env-chips li {
                padding: 3px 10px;
                border: 1px solid var(--fm-line);
                border-radius: 14px;
                background: var(--fm-tier);
                font-family: var(--fm-mono);
                font-size: 12px;
            }

            .fm-env-chips li span {
                margin-right: 6px;
                color: var(--fm-muted);
                font-family: inherit;
            }

            .fm-env-badge {
                display: inline-block;
                padding: 1px 8px;
                border-radius: 10px;
                background: var(--fm-hover);
                color: var(--fm-ink);
                font-size: 11.5px;
                font-weight: 600;
                line-height: 18px;
                white-space: nowrap;
            }

            .fm-env-badge.is-ok { background: var(--fm-success-soft); color: var(--fm-success); }
            .fm-env-badge.is-warn { background: var(--fm-warning-soft); color: var(--fm-warning); }
            .fm-env-badge.is-bad { background: var(--fm-danger-soft); color: var(--fm-danger); }

            /* detail tabs */
            .fm-env-grid2 {
                display: grid;
                grid-template-columns: repeat(2, minmax(0, 1fr));
                gap: 14px;
                margin-top: 14px;
            }

            .fm-env-box {
                min-width: 0;
                margin-top: 14px;
                padding: 14px 16px;
                border: 1px solid var(--fm-line);
                border-radius: 12px;
            }

            .fm-env-grid2 > .fm-env-box {
                margin-top: 0;
            }

            .fm-env-sub {
                margin: 18px 0 8px;
                font-size: 13.5px;
                font-weight: 650;
            }

            .fm-env-box .fm-env-sub {
                margin-top: 14px;
            }

            .fm-env-kv {
                display: grid;
                grid-template-columns: minmax(130px, auto) minmax(0, 1fr);
                gap: 6px 16px;
                margin: 0;
                font-size: 13px;
            }

            .fm-env-kv dt {
                color: var(--fm-muted);
                font-weight: 500;
            }

            .fm-env-kv dd {
                min-width: 0;
                margin: 0;
                overflow-wrap: anywhere;
            }

            .fm-env-kv code,
            .fm-env-table code {
                color: var(--fm-ink);
                font-size: 12px;
            }

            .fm-env-tablewrap {
                max-width: 100%;
                overflow: auto;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
            }

            .fm-env-tablewrap.is-short {
                max-height: 260px;
            }

            .fm-env-tablewrap.is-tall {
                max-height: calc(100vh - 340px);
                min-height: 160px;
            }

            .fm-env-table {
                width: 100%;
                margin: 0;
                border-collapse: collapse;
                font-size: 12.5px;
            }

            .fm-env-table th {
                position: sticky;
                top: 0;
                z-index: 1;
                padding: 7px 10px;
                border-bottom: 1px solid var(--fm-line);
                background: var(--fm-tier);
                color: var(--fm-muted);
                font-size: 11.5px;
                font-weight: 600;
                text-align: left;
                white-space: nowrap;
            }

            .fm-env-table td {
                padding: 6px 10px;
                border-bottom: 1px solid var(--fm-line);
                vertical-align: top;
            }

            .fm-env-table tbody tr:last-child td {
                border-bottom: 0;
            }

            .fm-env-table tbody tr:hover td {
                background: var(--fm-hover);
            }

            .fm-env-table .is-num {
                text-align: right;
                white-space: nowrap;
            }

            .fm-env-table .is-mono,
            .is-mono {
                font-family: var(--fm-mono);
                font-size: 12px;
            }

            .fm-env-col-bar {
                width: 160px;
            }

            .fm-env-barcell {
                display: flex;
                align-items: center;
                gap: 8px;
            }

            .fm-env-barcell .fm-env-meter {
                flex: 1;
                margin: 0;
            }

            .fm-env-barcell span {
                min-width: 34px;
                font-size: 12px;
                text-align: right;
            }

            #fm-env-svc tr.is-minor {
                display: none;
            }

            #fm-env-svc.is-all tr.is-minor {
                display: table-row;
            }

            .fm-env-toggle {
                display: inline-flex;
                align-items: center;
                gap: 6px;
                margin: 0 0 0 auto;
                color: var(--fm-muted);
                font-size: 12.5px;
                font-weight: 500;
                cursor: pointer;
            }

            .fm-env-stack {
                display: flex;
                height: 12px;
                margin-bottom: 8px;
                overflow: hidden;
                border-radius: 6px;
                background: var(--fm-hover);
            }

            .fm-env-stack .is-used, .fm-env-legend .is-used::before { background: var(--fm-accent); }
            .fm-env-stack .is-shared, .fm-env-legend .is-shared::before { background: var(--fm-ic-tar); }
            .fm-env-stack .is-cache, .fm-env-legend .is-cache::before { background: color-mix(in srgb, var(--fm-accent) 35%, transparent); }

            .fm-env-legend {
                display: flex;
                flex-wrap: wrap;
                gap: 4px 14px;
                margin: 0 0 12px;
                padding: 0;
                list-style: none;
                color: var(--fm-muted);
                font-size: 12px;
            }

            .fm-env-legend li::before {
                content: "";
                display: inline-block;
                width: 9px;
                height: 9px;
                margin-right: 5px;
                border-radius: 2px;
                background: var(--fm-hover);
            }

            .fm-env-extlist {
                display: flex;
                flex-wrap: wrap;
                gap: 5px;
            }

            .fm-env-loading {
                padding: 30px 0;
                color: var(--fm-muted);
                text-align: center;
            }

            /* scheduled jobs */
            .fm-env-jobs td {
                vertical-align: middle;
            }

            .fm-env-jobs {
                table-layout: fixed;
            }

            .fm-env-src {
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            /* long commands: two lines, the full text is in the tooltip */
            .fm-env-cmd code {
                display: -webkit-box;
                overflow: hidden;
                white-space: normal;
                word-break: break-all;
                -webkit-box-orient: vertical;
                -webkit-line-clamp: 2;
            }

            .fm-env-cmd code {
                display: block;
                overflow: hidden;
                text-overflow: ellipsis;
                white-space: nowrap;
            }

            .fm-env-warn {
                margin-top: 4px;
                color: var(--fm-warning);
                font-size: 12px;
                font-weight: 600;
                white-space: normal;
            }

            .fm-env-table tr.is-off td {
                opacity: .55;
            }

            .fm-env-table tr.is-off td.fm-env-actions {
                opacity: 1;
            }

            .fm-env-table tr.is-busy {
                opacity: .4;
                pointer-events: none;
            }

            .fm-env-actions {
                white-space: nowrap;
                text-align: right;
            }

            .fm-env-actions .fm-user-btn {
                display: inline-grid;
            }

            .fm-env-confirm {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 6px;
                margin-top: 6px;
                padding: 6px 8px;
                border-radius: 8px;
                background: var(--fm-danger-soft);
                color: var(--fm-danger);
                font-size: 12.5px;
                font-weight: 600;
            }

            .fm-env-flash {
                position: sticky;
                bottom: 0;
                margin: 10px 0 0;
                padding: 8px 12px;
                border-radius: 8px;
                background: var(--fm-success-soft);
                color: var(--fm-success);
                font-weight: 600;
            }

            .fm-env-flash.is-bad {
                background: var(--fm-danger-soft);
                color: var(--fm-danger);
            }

            .fm-env-flash[hidden] {
                display: none;
            }

            /* logs */
            .fm-env-logs:not([hidden]) {
                display: flex;
                flex-direction: column;
                height: 100%;
                padding-top: 14px;
            }

            .fm-env-logbar {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 10px;
                margin-bottom: 10px;
            }

            .fm-env-logsrc {
                flex: 1 1 360px;
                min-width: 0;
            }

            .fm-env-logsrc .fm-select {
                flex: none;
                width: 100%;
            }

            .fm-env-logsrc .fm-select-menu {
                min-width: 100%;
                max-height: 420px;
                overflow-y: auto;
            }

            .fm-env-n {
                width: 130px;
            }

            .fm-env-logbar .fm-segmented label {
                padding: 5px 12px;
            }

            .fm-env-filter {
                flex: 1 1 220px;
            }

            .fm-env-filter .form-control {
                height: 36px;
            }

            .fm-env-logtools {
                display: flex;
                align-items: center;
                gap: 6px;
                margin-left: auto;
            }

            .fm-env-logtools .fm-env-toggle {
                margin: 0 6px 0 0;
            }

            .fm-env-logmeta {
                margin: 0 0 8px;
                color: var(--fm-muted);
                font-size: 12.5px;
                overflow-wrap: anywhere;
            }

            .fm-env-logmeta code {
                color: var(--fm-ink);
            }

            .fm-env-warntext {
                color: var(--fm-warning);
                font-weight: 600;
            }

            .fm-env-logview {
                flex: 1;
                min-height: 200px;
                overflow: auto;
                padding: 8px 0;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                background: #11131A;
                color: #D7DAE6;
                font-family: var(--fm-mono);
                font-size: 12px;
                line-height: 1.55;
            }

            .fm-env-line {
                padding: 0 12px;
                white-space: pre;
            }

            .fm-env-logview.is-wrap .fm-env-line {
                white-space: pre-wrap;
                overflow-wrap: anywhere;
            }

            .fm-env-line:hover {
                background: rgba(255, 255, 255, .05);
            }

            .fm-env-line.is-error {
                color: #FF9B93;
                background: rgba(240, 82, 72, .08);
            }

            .fm-env-line.is-warn {
                color: #F5C26B;
            }

            .fm-env-line mark {
                padding: 0 1px;
                border-radius: 2px;
                background: #F5C26B;
                color: #11131A;
            }

            .fm-env-noline {
                padding: 20px;
                text-align: center;
            }

            @media (max-width: 1100px) {
                .fm-env-cards {
                    grid-template-columns: repeat(2, minmax(0, 1fr));
                }
            }

            @media (max-width: 860px) {
                .fm-env-cards,
                .fm-env-grid2 {
                    grid-template-columns: minmax(0, 1fr);
                }

                .fm-env-main {
                    height: auto;
                    overflow: visible;
                }

                .fm-env .fm-set-nav {
                    border-radius: 12px 12px 0 0;
                }

                .fm-env-logview {
                    height: 60vh;
                    flex: none;
                }

                .fm-env-tablewrap.is-tall {
                    max-height: 60vh;
                }
            }

            .fm-env-card.is-wide {
                grid-column: span 2;
            }

            .fm-env-card.is-full {
                grid-column: 1 / -1;
            }

            @media (max-width: 860px) {
                .fm-env-card.is-wide,
                .fm-env-card.is-full {
                    grid-column: auto;
                }
            }

            .fm-account-icon.is-env {
                background: color-mix(in srgb, var(--fm-ic-link) 14%, transparent);
                color: var(--fm-ic-link);
            }


            /* ---- coloured tiles: one colour per topic, the same on Settings, Environment and the account menu ---- */
            .fm-set-tab[data-tab="appearance"], .fm-set-panel[data-tab="appearance"], .fm-set-tab[data-tab="processes"], .fm-set-panel[data-tab="processes"] { --c: var(--fm-ic-pink); }
            .fm-set-tab[data-tab="regional"], .fm-set-panel[data-tab="regional"], .fm-set-tab[data-tab="jobs"], .fm-set-panel[data-tab="jobs"] { --c: var(--fm-ic-cyan); }
            .fm-set-tab[data-tab="files"], .fm-set-panel[data-tab="files"] { --c: var(--fm-folder); }
            .fm-set-tab[data-tab="uploads"], .fm-set-panel[data-tab="uploads"], .fm-set-tab[data-tab="logs"], .fm-set-panel[data-tab="logs"] { --c: var(--fm-ic-download); }
            .fm-set-tab[data-tab="viewer"], .fm-set-panel[data-tab="viewer"], .fm-set-tab[data-tab="memory"], .fm-set-panel[data-tab="memory"] { --c: var(--fm-ic-tar); }
            .fm-set-tab[data-tab="access"], .fm-set-panel[data-tab="access"], .fm-set-tab[data-tab="security"], .fm-set-panel[data-tab="security"] { --c: var(--fm-ic-delete); }
            .fm-set-tab[data-tab="network"], .fm-set-panel[data-tab="network"] { --c: var(--fm-ic-archive); }
            .fm-set-tab[data-tab="advanced"], .fm-set-panel[data-tab="advanced"], .fm-set-tab[data-tab="system"], .fm-set-panel[data-tab="system"] { --c: var(--fm-ic-neutral); }
            .fm-set-tab[data-tab="users"], .fm-set-panel[data-tab="users"], .fm-set-tab[data-tab="web"], .fm-set-panel[data-tab="web"] { --c: var(--fm-ic-indigo); }
            .fm-set-tab[data-tab="overview"], .fm-set-panel[data-tab="overview"] { --c: var(--fm-ic-select); }
            .fm-set-tab[data-tab="storage"], .fm-set-panel[data-tab="storage"] { --c: var(--fm-ic-edit); }
            .fm-set-tab[data-tab="services"], .fm-set-panel[data-tab="services"] { --c: var(--fm-ic-link); }
            .fm-set-tab[data-tab="setup"], .fm-set-panel[data-tab="setup"] { --c: var(--fm-ic-create); }

            .fm-set-tab {
                padding: 5px 8px;
            }

            .fm-set-tab > i.fa {
                display: grid;
                flex: none;
                place-items: center;
                width: 26px;
                height: 26px;
                border-radius: 7px;
                background: color-mix(in srgb, var(--c, var(--fm-ic-neutral)) 14%, transparent);
                color: var(--c, var(--fm-ic-neutral));
                font-size: 13px;
                transition: background-color .15s, color .15s;
            }

            .fm-set-tab:hover > i.fa {
                background: color-mix(in srgb, var(--c, var(--fm-ic-neutral)) 24%, transparent);
            }

            /* the open tab: a solid tile (the surface colour keeps the icon readable in light and dark) */
            .fm-set-tab.is-active > i.fa {
                background: var(--c, var(--fm-accent));
                color: var(--fm-surface);
            }

            .fm-set-tab.is-active {
                color: var(--fm-ink);
            }

            .fm-set-panel-head h2 i {
                display: grid;
                place-items: center;
                width: 28px;
                height: 28px;
                border-radius: 8px;
                background: color-mix(in srgb, var(--c, var(--fm-accent)) 14%, transparent);
                color: var(--c, var(--fm-accent)) !important;
                font-size: 14px;
            }

            /* Environment cards and boxes: their icon in the colour of the tab they belong to */
            .fm-env-main h3 > i.fa-server, .fm-env-main h3 > i.fa-terminal, .fm-env-main h3 > i.fa-cogs { color: var(--fm-ic-neutral) !important; }
            .fm-env-main h3 > i.fa-microchip { color: var(--fm-ic-tar) !important; }
            .fm-env-main h3 > i.fa-tasks { color: var(--fm-ic-pink) !important; }
            .fm-env-main h3 > i.fa-hdd-o { color: var(--fm-ic-edit) !important; }
            .fm-env-main h3 > i.fa-heartbeat, .fm-env-main h3 > i.fa-shield, .fm-env-main h3 > i.fa-ban { color: var(--fm-ic-delete) !important; }
            .fm-env-main h3 > i.fa-globe { color: var(--fm-ic-indigo) !important; }
            .fm-env-main h3 > i.fa-refresh { color: var(--fm-ic-download) !important; }
            .fm-env-main h3 > i.fa-sign-in { color: var(--fm-ic-link) !important; }
            .fm-env-main h3 > i.fa-clock-o { color: var(--fm-ic-cyan) !important; }

            /* account menu tiles */
            .fm-account-icon.is-settings { background: color-mix(in srgb, var(--fm-ic-select) 14%, transparent) !important; color: var(--fm-ic-select) !important; }
            .fm-account-icon.is-env { background: color-mix(in srgb, var(--fm-ic-link) 14%, transparent) !important; color: var(--fm-ic-link) !important; }
            .fm-account-icon.is-password { background: color-mix(in srgb, var(--fm-ic-edit) 16%, transparent) !important; color: var(--fm-ic-edit) !important; }
            .fm-account-icon.is-help { background: color-mix(in srgb, var(--fm-ic-tar) 14%, transparent) !important; color: var(--fm-ic-tar) !important; }
            .fm-account-icon.is-setup, .fm-help-icon.is-setup { background: color-mix(in srgb, var(--fm-ic-create) 14%, transparent) !important; color: var(--fm-ic-create) !important; }

            .fm-account-icon.is-errors { background: color-mix(in srgb, var(--fm-ic-delete) 14%, transparent) !important; color: var(--fm-ic-delete) !important; }

            .fm-account-count {
                margin-left: auto;
                align-self: center;
                min-width: 22px;
                padding: 1px 7px;
                border-radius: 999px;
                background: var(--fm-danger-solid);
                color: #fff;
                font-size: 12px;
                font-weight: 700;
                text-align: center;
            }

            .fm-account-toggle.has-errors .fm-avatar::before {
                content: "";
                position: absolute;
                bottom: -2px;
                right: -2px;
                width: 10px;
                height: 10px;
                border: 2px solid var(--fm-surface);
                border-radius: 50%;
                background: var(--fm-danger-solid);
            }

            /* ---- Settings: export / import ---- */
            .fm-inline-form {
                display: inline;
                margin: 0;
            }

            #fm-imp-modal .modal-title i {
                margin-right: 4px;
                color: var(--fm-accent);
            }

            .fm-imp-drop {
                position: relative;
                display: flex;
                align-items: center;
                gap: 14px;
                padding: 16px 18px;
                border: 1.5px dashed var(--fm-line-strong);
                border-radius: 12px;
                background: var(--fm-tier);
                cursor: pointer;
            }

            .fm-imp-drop:hover {
                border-color: var(--fm-accent);
            }

            .fm-imp-drop > i {
                color: var(--fm-accent);
                font-size: 26px;
            }

            .fm-imp-drop strong,
            .fm-imp-drop small {
                display: block;
            }

            .fm-imp-drop small {
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-imp-drop input {
                position: absolute;
                inset: 0;
                opacity: 0;
                cursor: pointer;
            }

            .fm-imp-from {
                margin: 14px 0 10px;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-imp-grid {
                display: grid;
                grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
                gap: 16px;
            }

            .fm-imp-grid h6 {
                display: flex;
                align-items: center;
                gap: 8px;
                margin: 0 0 6px;
                color: var(--fm-muted);
                font-size: 13px;
                font-weight: 600;
            }

            .fm-imp-list {
                max-height: 190px;
                margin: 0;
                padding: 0;
                overflow-y: auto;
                list-style: none;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                font-size: 13px;
            }

            .fm-imp-list li {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 4px 8px;
                padding: 6px 10px;
            }

            .fm-imp-list li + li {
                border-top: 1px solid var(--fm-line);
            }

            .fm-imp-list li span {
                color: var(--fm-muted);
                overflow-wrap: anywhere;
            }

            .fm-imp-list li .fm-env-badge {
                color: inherit;
            }

            .fm-imp-none {
                color: var(--fm-muted);
            }

            .fm-imp-warn {
                margin: 12px 0 0;
                padding: 8px 12px;
                border-radius: 8px;
                background: var(--fm-warning-soft);
                list-style: none;
                font-size: 13px;
            }

            .fm-imp-warn i {
                color: var(--fm-warning);
            }

            .fm-imp-signout {
                margin: 10px 0 0;
                padding: 8px 12px;
                border-radius: 8px;
                background: var(--fm-danger-soft);
                font-size: 13px;
            }

            .fm-imp-pwd {
                display: block;
                max-width: 320px;
                margin-top: 14px;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-imp-pwd input {
                margin-top: 4px;
            }

            .fm-imp-status {
                margin: 12px 0 0;
                padding: 8px 12px;
                border-radius: 8px;
                font-size: 13.5px;
            }

            .fm-imp-status.is-busy { background: var(--fm-accent-soft); }
            .fm-imp-status.is-ok { background: var(--fm-success-soft); }
            .fm-imp-status.is-error { background: var(--fm-danger-soft); }

            .fm-imp-note {
                margin-right: auto;
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-imp-note i {
                color: var(--fm-success);
            }

            @media (max-width: 767.98px) {
                .fm-imp-grid {
                    grid-template-columns: 1fr;
                }

                .fm-imp-note {
                    display: none;
                }
            }

            /* ---- Error log ---- */
            .fm-errlog {
                display: flex;
                flex-direction: column;
                height: calc(100vh - 186px);
                min-height: 420px;
                margin: 0;
                padding: 14px 16px;
            }

            .fm-errlog-bar {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 10px;
                margin-bottom: 12px;
            }

            .fm-errlog-bar .fm-segmented em {
                margin-left: 2px;
                color: var(--fm-muted);
                font-size: 12px;
                font-style: normal;
            }

            .fm-errlog-search {
                flex: 1 1 220px;
                max-width: 360px;
                margin-left: auto;
            }

            .fm-errlog-list {
                flex: 1 1 auto;
                min-height: 0;
                overflow-y: auto;
            }

            .fm-errlog-item {
                border: 1px solid var(--fm-line);
                border-radius: 9px;
            }

            .fm-errlog-item + .fm-errlog-item {
                margin-top: 5px;
            }

            .fm-errlog-item.is-new {
                border-color: color-mix(in srgb, var(--fm-danger) 40%, var(--fm-line));
            }

            .fm-errlog-item summary {
                display: flex;
                align-items: flex-start;
                gap: 10px;
                padding: 8px 12px;
                cursor: pointer;
                list-style: none;
            }

            .fm-errlog-item summary::-webkit-details-marker {
                display: none;
            }

            .fm-errlog-kind { width: 16px; text-align: center; }
            .fm-errlog-item.is-bad .fm-errlog-kind { color: var(--fm-danger); }
            .fm-errlog-item.is-warn .fm-errlog-kind { color: var(--fm-warning); }
            .fm-errlog-item.is-note .fm-errlog-kind { color: var(--fm-muted); }

            .fm-errlog-msg {
                flex: 1 1 auto;
                min-width: 0;
                font-size: 13.5px;
                overflow-wrap: anywhere;
            }

            .fm-errlog-when {
                flex: none;
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-errlog-item .fm-env-kv {
                margin: 0 12px 6px 38px;
                font-size: 13px;
            }

            .fm-errlog-item .fm-env-kv code {
                word-break: break-all;
            }

            .fm-errlog-actions {
                margin: 0 12px 10px 38px;
                font-size: 12.5px;
            }

            .fm-errlog-empty {
                padding: 30px 10px;
                color: var(--fm-muted);
                text-align: center;
            }

            .fm-errlog-empty i {
                color: var(--fm-success);
            }

            .fm-errlog-clear {
                display: inline;
                margin: 0;
            }

            #fm-errlog-clear.is-armed {
                border-color: var(--fm-danger);
                color: var(--fm-danger);
            }

            @media (max-width: 767.98px) {
                .fm-errlog {
                    height: auto;
                }

                .fm-errlog-search {
                    max-width: none;
                    margin-left: 0;
                }

                .fm-errlog-item .fm-env-kv,
                .fm-errlog-actions {
                    margin-left: 12px;
                }
            }

            /* ---- Setup check ---- */
            .fm-setup-layout {
                display: grid;
                grid-template-columns: 300px minmax(0, 1fr);
                gap: 16px;
                height: calc(100vh - 186px);
                min-height: 420px;
            }

            .fm-setup-side,
            .fm-setup-main {
                margin: 0;
                padding: 14px 16px;
                overflow-y: auto;
            }

            .fm-setup-side {
                display: flex;
                flex-direction: column;
                padding: 20px 18px 16px;
            }

            .fm-setup-head-card {
                display: flex;
                align-items: center;
                gap: 14px;
                margin-bottom: 14px;
            }

            .fm-setup-score {
                position: relative;
                flex: none;
                width: 92px;
                height: 92px;
            }

            .fm-setup-ring {
                width: 100%;
                height: 100%;
            }

            .fm-setup-ring circle {
                fill: none;
                stroke-width: 9;
                stroke-linecap: butt;
            }

            .fm-setup-ring .is-track { stroke: var(--fm-tier); }
            .fm-setup-ring .is-fail { stroke: var(--fm-danger); }
            .fm-setup-ring .is-warn { stroke: var(--fm-warning); }
            .fm-setup-ring .is-info { stroke: color-mix(in srgb, var(--fm-muted) 55%, transparent); }
            .fm-setup-ring .is-ok { stroke: var(--fm-success); }

            .fm-setup-ring-label {
                position: absolute;
                inset: 0;
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                line-height: 1.1;
            }

            .fm-setup-ring-label strong {
                font-size: 24px;
                font-weight: 700;
                letter-spacing: -.02em;
                color: var(--fm-ink);
            }

            .fm-setup-ring-label span {
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-setup-verdict {
                margin: 0;
                font-size: 15px;
                font-weight: 700;
                line-height: 1.3;
            }

            .fm-setup-verdict.is-fail { color: var(--fm-danger); }
            .fm-setup-verdict.is-warn { color: var(--fm-warning); }
            .fm-setup-verdict.is-ok { color: var(--fm-success); }

            .fm-setup-checked {
                margin: 4px 0 0;
                color: var(--fm-muted);
                font-size: 12.5px;
                line-height: 1.45;
            }

            .fm-setup-filters {
                display: grid;
                gap: 2px;
                padding: 4px;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                background: var(--fm-tier);
            }

            .fm-setup-filter {
                display: flex;
                align-items: center;
                gap: 10px;
                width: 100%;
                padding: 5px 10px;
                border: 0;
                border-radius: 7px;
                background: transparent;
                color: var(--fm-ink);
                font-size: 13.5px;
                text-align: left;
                transition: background-color .12s;
            }

            .fm-setup-filter:hover:not(:disabled) {
                background: var(--fm-hover);
            }

            .fm-setup-filter[aria-pressed="true"] {
                background: var(--fm-surface);
                box-shadow: var(--fm-shadow);
                font-weight: 600;
            }

            .fm-setup-filter:disabled {
                opacity: .45;
                cursor: default;
            }

            .fm-setup-filter i { width: 16px; text-align: center; }
            .fm-setup-filter.is-fail i { color: var(--fm-danger); }
            .fm-setup-filter.is-warn i { color: var(--fm-warning); }
            .fm-setup-filter.is-info i { color: var(--fm-muted); }
            .fm-setup-filter.is-ok i { color: var(--fm-success); }

            .fm-setup-filter em {
                margin-left: auto;
                min-width: 26px;
                padding: 0 7px;
                border-radius: 999px;
                background: var(--fm-surface);
                color: var(--fm-muted);
                font-size: 12px;
                font-style: normal;
                font-weight: 600;
                text-align: center;
            }

            .fm-setup-filter.is-fail:not(:disabled) em { background: var(--fm-danger-soft); color: var(--fm-danger); }
            .fm-setup-filter.is-warn:not(:disabled) em { background: var(--fm-warning-soft); color: var(--fm-warning); }

            .fm-setup-side-h {
                margin: 18px 0 6px;
                color: var(--fm-muted);
                font-size: 11.5px;
                font-weight: 700;
                letter-spacing: .06em;
                text-transform: uppercase;
            }

            .fm-setup-facts {
                margin: 0;
                padding: 0;
                list-style: none;
            }

            .fm-setup-facts li {
                display: grid;
                grid-template-columns: 16px 50px minmax(0, 1fr);
                gap: 8px;
                padding: 5px 0;
                font-size: 13px;
            }

            .fm-setup-facts li + li {
                border-top: 1px solid var(--fm-line);
            }

            .fm-setup-facts li > i.fa {
                margin-top: 3px;
                color: var(--fm-muted) !important;
                text-align: center;
            }

            .fm-setup-fact-k {
                color: var(--fm-muted);
            }

            .fm-setup-facts strong {
                display: block;
                font-weight: 600;
                overflow-wrap: break-word;
            }

            .fm-setup-facts strong span {
                color: var(--fm-muted);
                font-weight: 500;
            }

            .fm-setup-facts small {
                display: block;
                color: var(--fm-muted);
                font-size: 12px;
                overflow-wrap: break-word;
            }

            .fm-setup-facts code {
                color: inherit;
                font-size: 12px;
                overflow-wrap: break-word;
            }

            .fm-setup-facts strong code {
                font-size: 12.5px;
                font-weight: 500;
            }

            .fm-setup-intro {
                margin: 0 0 12px;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-setup-intro i {
                color: var(--fm-success);
            }

            /* a status chosen in the side panel shows only that status (passing included when chosen) */
            .fm-setup[data-only] .fm-setup-item {
                display: none !important;
            }

            .fm-setup[data-only="fail"] .fm-setup-item[data-status="fail"],
            .fm-setup[data-only="warn"] .fm-setup-item[data-status="warn"],
            .fm-setup[data-only="info"] .fm-setup-item[data-status="info"],
            .fm-setup[data-only="ok"] .fm-setup-item[data-status="ok"] {
                display: block !important;
            }

            .fm-setup-group + .fm-setup-group {
                margin-top: 14px;
            }

            .fm-setup-group h3 {
                display: flex;
                align-items: center;
                gap: 8px;
                margin: 0 0 6px;
                font-size: 14px;
                font-weight: 700;
            }

            .fm-setup .fm-setup-group h3 > i.fa {
                color: var(--fm-ic-create) !important;
            }

            .fm-setup-pass {
                color: var(--fm-muted);
                font-size: 12.5px;
                font-weight: 500;
            }

            .fm-setup.show-ok .fm-setup-pass {
                display: none;
            }


            .fm-setup-head {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 6px 14px;
            }

            .fm-setup-tools {
                display: flex;
                align-items: center;
                gap: 8px;
                margin-left: auto;
            }

            .fm-setup-tools .fm-env-toggle {
                margin: 0;
            }

            .fm-setup-item {
                border: 1px solid var(--fm-line);
                border-radius: 9px;
                background: var(--fm-surface);
            }

            .fm-setup-item + .fm-setup-item {
                margin-top: 5px;
            }

            .fm-setup:not(.show-ok) .fm-setup-item[data-status="ok"] {
                display: none;
            }

            .fm-setup-row {
                display: flex;
                align-items: flex-start;
                gap: 10px;
                padding: 7px 12px;
                list-style: none;
                cursor: default;
            }

            summary.fm-setup-row {
                cursor: pointer;
            }

            summary.fm-setup-row::-webkit-details-marker {
                display: none;
            }

            .fm-setup-st { width: 16px; text-align: center; }
            .fm-setup-item.is-ok .fm-setup-st { color: var(--fm-success); }
            .fm-setup-item.is-fail .fm-setup-st { color: var(--fm-danger); }
            .fm-setup-item.is-warn .fm-setup-st { color: var(--fm-warning); }
            .fm-setup-item.is-info .fm-setup-st { color: var(--fm-muted); }
            .fm-setup-item.is-fail { border-color: color-mix(in srgb, var(--fm-danger) 40%, var(--fm-line)); }

            .fm-setup-row > i,
            .fm-setup-row > .fm-env-badge {
                flex: none;
                margin-top: 2px;
            }

            .fm-setup-title {
                flex: none;
                max-width: 45%;
                font-weight: 600;
                font-size: 13.5px;
            }

            .fm-setup-val {
                flex: 1 1 auto;
                min-width: 0;
                color: var(--fm-muted);
                font-size: 13px;
                overflow-wrap: anywhere;
            }

            .fm-env-badge.is-note {
                color: var(--fm-muted);
            }

            .fm-setup-chev {
                color: var(--fm-muted);
                transition: transform .15s;
            }

            details[open] > summary .fm-setup-chev {
                transform: rotate(180deg);
            }

            .fm-setup-why {
                margin: -2px 12px 8px 38px;
                color: var(--fm-muted);
                font-size: 13px;
            }


            .fm-setup-body {
                margin: 0 12px 10px 38px;
            }

            .fm-setup-fix,
            .fm-setup-probe {
                margin: 0 0 6px;
                font-size: 13px;
            }

            .fm-setup-probe-out {
                margin-left: 6px;
                color: var(--fm-muted);
            }

            .fm-setup-cmd {
                display: grid;
                grid-template-columns: 112px minmax(0, 1fr) auto;
                align-items: start;
                gap: 8px;
                margin-top: 5px;
            }

            .fm-setup-cmd > span {
                padding-top: 6px;
                color: var(--fm-muted);
                font-size: 12px;
            }

            .fm-setup-cmd pre {
                margin: 0;
                padding: 6px 10px;
                overflow-x: auto;
                border-radius: 7px;
                background: var(--fm-tier);
                border: 1px solid var(--fm-line);
                font-size: 12.5px;
                white-space: pre-wrap;
                word-break: break-all;
            }

            .fm-setup-cmd code {
                color: var(--fm-ink);
            }

            .fm-env-main .fm-setup .fm-setup-item {
                background: transparent;
            }

            .fm-help-setup {
                margin-bottom: 16px;
            }

            .fm-setup-page .fm-env-head-actions .btn,
            .fm-setup-page .fm-env-head-actions .fm-env-toggle {
                white-space: nowrap;
            }

            @media (max-width: 767.98px) {
                .fm-setup-page .fm-env-head-actions {
                    flex-wrap: wrap;
                }

                .fm-setup-layout {
                    grid-template-columns: 1fr;
                    height: auto;
                }

                .fm-setup-side,
                .fm-setup-main {
                    overflow: visible;
                }

                .fm-setup-cmd {
                    grid-template-columns: minmax(0, 1fr) auto;
                }

                .fm-setup-cmd > span {
                    grid-column: 1 / -1;
                    padding: 0;
                }

                .fm-setup-why,
                .fm-setup-body {
                    margin-left: 12px;
                }

                .fm-setup-val {
                    display: none;
                }
            }

            /* the last grey action icons */
            .fm-topbar .fm-btn i.fa-download { color: var(--fm-ic-download); }
            .fm-summary i.fa-folder-o { color: var(--fm-folder); }
            .fm-summary i.fa-hdd-o { color: var(--fm-ic-edit); }

            /* ---- Change password page ---- */
            .fm-pwd-grid {
                display: grid;
                grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
                gap: 20px;
                align-items: start;
            }

            @media (max-width: 860px) {
                .fm-pwd-grid {
                    grid-template-columns: minmax(0, 1fr);
                }
            }

            .fm-pwd-card,
            .fm-gen-card {
                padding: 0;
            }

            .fm-pwd-body {
                display: flex;
                flex-direction: column;
                gap: 12px;
                padding: 18px 24px 16px;
            }

            .fm-pwd-page .fm-page-head {
                margin-bottom: 14px;
            }

            .fm-pwd-field label {
                display: block;
                margin-bottom: 5px;
                color: var(--fm-ink);
                font-size: 13.5px;
                font-weight: 600;
            }

            .fm-pwd-field .form-control {
                padding-right: 44px;
                font-size: 15px; /* at 14px Chrome drops the "_" of DejaVu Sans Mono inside inputs */
                font-family: var(--fm-mono);
                letter-spacing: .02em;
            }

            .fm-pwd-field .form-control[type=password] {
                letter-spacing: .12em;
            }

            .fm-pwd-field .form-control.is-invalid {
                border-color: var(--fm-danger);
                background-image: none;
            }

            .fm-pwd-sep {
                display: flex;
                align-items: center;
                gap: 12px;
                margin-top: 2px;
                color: var(--fm-muted);
                font-size: 12px;
                font-weight: 600;
                letter-spacing: .06em;
                text-transform: uppercase;
            }

            .fm-pwd-sep::after {
                content: "";
                flex: 1;
                border-top: 1px solid var(--fm-line);
            }

            /* strength meter: four bars that fill and change colour */
            .fm-strength {
                display: flex;
                align-items: center;
                gap: 12px;
                margin-top: -6px;
            }

            .fm-strength-bars {
                display: grid;
                grid-template-columns: repeat(4, 1fr);
                gap: 4px;
                flex: 0 0 132px;
            }

            .fm-strength-bars i {
                height: 5px;
                border-radius: 3px;
                background: var(--fm-line);
                transition: background-color .25s;
            }

            .fm-strength-label {
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-strength[data-level="1"] { --fm-meter: var(--fm-danger); }
            .fm-strength[data-level="2"] { --fm-meter: var(--fm-warning); }
            .fm-strength[data-level="3"] { --fm-meter: var(--fm-accent); }
            .fm-strength[data-level="4"] { --fm-meter: var(--fm-success); }

            .fm-strength[data-level="1"] .fm-strength-bars i:nth-child(-n+1),
            .fm-strength[data-level="2"] .fm-strength-bars i:nth-child(-n+2),
            .fm-strength[data-level="3"] .fm-strength-bars i:nth-child(-n+3),
            .fm-strength[data-level="4"] .fm-strength-bars i {
                background: var(--fm-meter);
            }

            .fm-strength:not([data-level="0"]) .fm-strength-label {
                color: var(--fm-meter);
                font-weight: 600;
            }

            .fm-pwd-rules {
                display: flex;
                flex-direction: column;
                gap: 4px;
                margin: 0;
                padding: 10px 14px;
                border-radius: 10px;
                background: var(--fm-tier);
                list-style: none;
                font-size: 13px;
                color: var(--fm-muted);
            }

            .fm-pwd-rules li {
                display: flex;
                align-items: center;
                gap: 8px;
                transition: color .2s;
            }

            .fm-pwd-rules li i {
                width: 14px;
                text-align: center;
            }

            .fm-pwd-rules li.is-ok { color: var(--fm-success); }
            .fm-pwd-rules li.is-bad { color: var(--fm-danger); }

            .fm-pwd-foot {
                display: flex;
                justify-content: flex-end;
                flex-wrap: wrap;
                gap: 10px;
                padding: 12px 24px;
                border-top: 1px solid var(--fm-line);
                background: var(--fm-tier);
            }

            .fm-pwd-foot .btn:disabled {
                opacity: .5;
            }

            /* generator */
            .fm-gen-card {
                display: flex;
                flex-direction: column;
                gap: 14px;
                padding: 18px 22px 20px;
            }

            .fm-gen-head {
                display: flex;
                align-items: flex-start;
                gap: 14px;
            }

            .fm-gen-head h2 {
                margin: 0 0 2px;
                font-size: 16px;
                font-weight: 650;
            }

            .fm-gen-head p {
                margin: 0;
                color: var(--fm-muted);
                font-size: 13px;
            }

            .fm-gen-display {
                display: flex;
                align-items: center;
                gap: 8px;
                min-height: 66px;
                padding: 10px 10px 10px 16px;
                border: 1px solid var(--fm-line);
                border-radius: 12px;
                background:
                    radial-gradient(120% 140% at 0% 0%, color-mix(in srgb, var(--fm-accent) 9%, transparent), transparent 60%),
                    var(--fm-tier);
            }

            .fm-gen-value {
                flex: 1;
                min-width: 0;
                font-family: var(--fm-mono);
                font-size: 19px;
                font-weight: 600;
                line-height: 1.45;
                letter-spacing: .03em;
                color: var(--fm-ink);
                overflow-wrap: anywhere;
                user-select: all;
            }

            .fm-gen-value .is-digit { color: var(--fm-accent); }
            .fm-gen-value .is-sym { color: var(--fm-ic-tar); }

            .fm-gen-tools {
                display: flex;
                flex-direction: column;
                gap: 4px;
            }

            .fm-gen-icon {
                display: grid;
                place-items: center;
                width: 34px;
                height: 34px;
                border: 0;
                border-radius: 8px;
                background: transparent;
                color: var(--fm-muted);
                transition: background-color .15s, color .15s;
            }

            .fm-gen-icon:hover {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            .fm-gen-icon:focus-visible {
                outline: 0;
                box-shadow: var(--fm-focus);
            }

            .fm-gen-icon.is-spinning i {
                animation: fm-gen-spin .45s ease;
            }

            @keyframes fm-gen-spin {
                to { transform: rotate(360deg); }
            }

            .fm-gen-strength {
                margin-top: -6px;
            }

            .fm-gen-options {
                display: flex;
                flex-direction: column;
                border-top: 1px solid var(--fm-line);
            }

            .fm-gen-row {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 16px;
                min-height: 46px;
                border-bottom: 1px dashed var(--fm-line);
            }

            .fm-gen-row[hidden] {
                display: none;
            }

            .fm-gen-opt-name {
                margin: 0;
                font-size: 13.5px;
                font-weight: 600;
            }

            .fm-gen-opt-name small {
                margin-left: 4px;
                color: var(--fm-muted);
                font-family: var(--fm-mono);
                font-weight: 400;
            }

            .fm-gen-range {
                display: flex;
                align-items: center;
                gap: 12px;
                flex: 0 1 230px;
            }

            .fm-gen-range .form-range {
                flex: 1;
            }

            .fm-gen-range .form-range::-webkit-slider-thumb {
                background: var(--fm-accent);
            }

            .fm-gen-range .form-range::-moz-range-thumb {
                background: var(--fm-accent);
            }

            .fm-gen-range .form-range:focus::-webkit-slider-thumb {
                box-shadow: var(--fm-focus);
            }

            .fm-gen-range .form-range:focus::-moz-range-thumb {
                box-shadow: var(--fm-focus);
            }

            .fm-gen-range-val {
                min-width: 66px;
                padding: 2px 8px;
                border-radius: 6px;
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-family: var(--fm-mono);
                font-size: 12.5px;
                font-weight: 600;
                text-align: center;
            }

            .fm-gen-card .form-switch .form-check-input {
                width: 2.4em;
                height: 1.3em;
                cursor: pointer;
            }

            .fm-gen-card .form-switch .form-check-input:checked {
                border-color: var(--fm-accent);
                background-color: var(--fm-accent);
            }

            .fm-gen-use {
                width: 100%;
                height: 44px;
                font-weight: 600;
            }

            @media (max-width: 860px) {
                .fm-gen-use i.fa-arrow-left {
                    transform: rotate(90deg);
                }
            }

            .fm-gen-note {
                display: flex;
                gap: 8px;
                margin: -6px 0 0;
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-gen-note i {
                margin-top: 3px;
            }

            .fm-topbar .fm-account-item.is-current {
                background: var(--fm-accent-soft);
            }

            .fm-topbar .fm-account-item.is-current strong {
                color: var(--fm-accent);
            }

            .fm-account-foot {
                padding: 6px;
                border-top: 1px solid var(--fm-line);
            }

            .fm-topbar .fm-account-signout,
            .fm-topbar .fm-account-signout:visited {
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 8px 10px;
                border-radius: 8px;
                color: var(--fm-danger);
                font-weight: 500;
            }

            .fm-topbar .fm-account-signout i.fa {
                width: 32px;
                color: var(--fm-danger) !important;
                opacity: 1;
                text-align: center;
            }

            .fm-topbar .fm-account-signout:hover,
            .fm-topbar .fm-account-signout:focus {
                background: var(--fm-danger-soft);
                color: var(--fm-danger);
            }

            .fm-account-version-row {
                display: flex;
                align-items: center;
                gap: 6px;
            }

            .fm-account-version-row .fm-account-version {
                flex: 1 1 auto;
                min-width: 0;
            }

            .fm-update-btn {
                flex: none;
                display: inline-flex;
                align-items: center;
                gap: 6px;
                margin-right: 4px;
                padding: 3px 10px;
                border: 1px solid var(--fm-line);
                border-radius: 999px;
                background: var(--fm-surface);
                color: var(--fm-muted);
                font-size: 12px;
                font-weight: 500;
                white-space: nowrap;
                transition: background-color .12s, color .12s, border-color .12s;
            }

            .fm-update-btn:hover,
            .fm-update-btn:focus-visible {
                border-color: var(--fm-line-strong);
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            .fm-update-btn.is-latest {
                color: var(--fm-success);
            }

            .fm-update-btn.has-update {
                border-color: var(--fm-accent);
                background: var(--fm-accent);
                color: #fff;
                font-weight: 600;
            }

            .fm-update-btn.has-update:hover {
                background: var(--fm-accent);
                color: #fff;
                filter: brightness(1.08);
            }

            .fm-update-btn:disabled {
                opacity: .7;
            }

            .fm-account-toggle .fm-avatar {
                position: relative;
            }

            .fm-account-toggle.has-update .fm-avatar::after {
                content: "";
                position: absolute;
                top: -2px;
                right: -2px;
                width: 10px;
                height: 10px;
                border: 2px solid var(--fm-surface);
                border-radius: 50%;
                background: var(--fm-accent);
            }

            #fm-update-modal .modal-title i {
                color: var(--fm-accent);
                margin-right: 4px;
            }

            .fm-update-versions {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 10px;
                margin-bottom: 14px;
                color: var(--fm-muted);
            }

            .fm-update-ver {
                padding: 3px 12px;
                border: 1px solid var(--fm-line);
                border-radius: 999px;
                background: var(--fm-tier);
                color: var(--fm-ink);
                font-size: 14px;
                font-weight: 600;
            }

            .fm-update-ver.is-new {
                border-color: transparent;
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
            }

            .fm-update-note {
                font-size: 13.5px;
            }

            .fm-update-notes {
                max-height: 260px;
                margin-bottom: 12px;
                padding: 4px 14px;
                overflow-y: auto;
                border: 1px solid var(--fm-line);
                border-radius: 10px;
                font-size: 13.5px;
            }

            .fm-update-notes section + section {
                border-top: 1px solid var(--fm-line);
            }

            .fm-update-notes h6 {
                margin: 10px 0 6px;
                font-size: 13.5px;
                font-weight: 700;
            }

            .fm-update-notes h6 small {
                margin-left: 6px;
                color: var(--fm-muted);
                font-weight: 500;
            }

            .fm-update-notes p,
            .fm-update-notes ul {
                margin: 0 0 8px;
            }

            .fm-update-notes ul {
                padding-left: 18px;
            }

            .fm-update-notes .fm-update-h {
                margin-top: 8px;
                font-weight: 600;
            }

            .fm-update-safe {
                display: flex;
                gap: 8px;
                margin: 0 0 4px;
                font-size: 13px;
            }

            .fm-update-safe i {
                margin-top: 3px;
                color: var(--fm-success);
            }

            .fm-update-status {
                display: flex;
                align-items: flex-start;
                gap: 8px;
                margin-top: 10px;
                padding: 10px 12px;
                border-radius: 8px;
                font-size: 13.5px;
            }

            .fm-update-status i {
                margin-top: 3px;
            }

            .fm-update-status.is-busy {
                background: var(--fm-accent-soft);
            }

            .fm-update-status.is-busy .fm-hint {
                display: block;
                margin-top: 2px;
            }

            .fm-update-status.is-ok {
                background: var(--fm-success-soft);
            }

            .fm-update-status.is-ok i {
                color: var(--fm-success);
            }

            .fm-update-status.is-error {
                background: var(--fm-danger-soft);
            }

            .fm-update-status.is-error i {
                color: var(--fm-danger);
            }

            #js-update-go i {
                color: inherit !important;
            }

            #fm-update-modal .fm-update-rollback {
                margin-right: auto;
                padding-left: 0;
                font-size: 13.5px;
                text-decoration: none;
            }

            #fm-update-modal .fm-update-rollback {
                --bs-btn-color: var(--fm-muted);
                --bs-btn-hover-color: var(--fm-danger);
                --bs-btn-active-color: var(--fm-danger);
            }

            #fm-update-modal .fm-update-rollback.is-armed {
                --bs-btn-color: var(--fm-danger);
                font-weight: 600;
            }

            .fm-topbar .fm-account-version,
            .fm-topbar .fm-account-version:visited {
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 6px 10px;
                border-radius: 8px;
                color: var(--fm-muted);
                font-size: 12.5px;
            }

            .fm-topbar .fm-account-version strong {
                color: var(--fm-ink);
                font-weight: 600;
            }

            .fm-topbar .fm-account-version i.fa-info-circle {
                width: 32px;
                color: var(--fm-muted) !important;
                text-align: center;
            }

            .fm-topbar .fm-account-version .fm-account-version-go {
                margin-left: auto;
                font-size: 11px;
                opacity: 0;
                transition: opacity .12s;
            }

            .fm-topbar .fm-account-version:hover,
            .fm-topbar .fm-account-version:focus {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            .fm-topbar .fm-account-version:hover .fm-account-version-go,
            .fm-topbar .fm-account-version:focus .fm-account-version-go {
                opacity: .7;
            }

            /* ---- upload from computer: results list (same rows as URL uploads) ---- */
            .fm-dz-results {
                margin-top: 16px;
            }

            .fm-dz-results.hidden {
                display: none !important;
            }

            .fm-dz-results .fm-url-head strong {
                color: var(--fm-ink);
            }

            .fm-dz-total {
                height: 4px;
                margin: -2px 0 10px;
                overflow: hidden;
                border-radius: 999px;
                background: var(--fm-tier);
            }

            .fm-dz-total span {
                display: block;
                width: 0;
                height: 100%;
                background: var(--fm-accent);
                transition: width .2s;
            }

            .fm-dz-total.is-idle {
                visibility: hidden;
            }

            #js-dz-list .fm-dz-row + .fm-dz-row {
                margin-top: 8px;
            }

            .fm-dz-row .fm-url-text small span[data-dz-size] strong {
                font-weight: 500;
            }

            .fm-dz-sub {
                font-family: var(--fm-mono);
                font-size: 12px;
            }

            .fm-dz-row.is-ok .fm-dz-state i {
                color: var(--fm-success);
            }

            .fm-dz-bar {
                display: block;
                height: 5px;
                margin-top: 6px;
                overflow: hidden;
                border-radius: 999px;
                background: var(--fm-tier);
                box-shadow: inset 0 0 0 1px var(--fm-line);
            }

            .fm-dz-bar .dz-upload {
                display: block;
                width: 0;
                height: 100%;
                border-radius: 999px;
                background: var(--fm-accent);
                transition: width .2s;
            }

            .fm-dz-row.is-ok .fm-dz-bar,
            .fm-dz-row.is-error .fm-dz-bar {
                display: none;
            }

            .fm-dz-error:empty {
                display: none;
            }

            .fm-dz-row.is-error .fm-dz-error {
                color: var(--fm-ink) !important;
            }

            .fm-dz-row.is-error .fm-url-icon {
                background: var(--fm-surface);
                color: var(--fm-danger);
            }

            .fm-dz-actions:empty {
                display: none;
            }

            .fm-dz-actions .btn {
                background: var(--fm-surface);
            }

            .fm-dz-actions .btn i.fa-eye {
                color: var(--fm-accent);
            }

            /* the drop area stays a clean target; files are listed below it */
            .fm-upload-card form.dropzone.dz-started {
                display: flex;
                min-height: 200px;
                padding: 0;
                border-style: dashed;
                background: var(--fm-tier);
            }

            .fm-upload-card form.dropzone.dz-started .dz-message {
                display: flex;
            }

            /* ---- copy / move pages (same parts as the copy modal) ---- */
            /* wrap normal words normally; only long paths may break anywhere */
            .fm-dest-note {
                word-break: normal;
                overflow-wrap: anywhere;
            }

            .fm-copy-page-grid {
                display: grid;
                grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
                gap: 16px;
                align-items: start;
            }

            .fm-copy-panel {
                padding: 18px 20px;
            }

            .fm-copy-panel h2.fm-copy-label + * {
                margin-top: 0;
            }

            .fm-copy-panel .fm-copy-label:not(:first-child) {
                margin-top: 18px;
            }

            .fm-copy-item i.fa-folder-o,
            .fm-copy-items li i.fa-folder-o {
                color: var(--fm-folder) !important;
            }

            .fm-copy-from {
                display: flex;
                align-items: center;
                gap: 8px;
                margin: 0;
                color: var(--fm-ink);
                font-family: var(--fm-mono);
                font-size: 13px;
                word-break: break-all;
            }

            .fm-copy-from i {
                color: var(--fm-folder);
            }

            .fm-copy-panel .fm-dest-list {
                height: auto;
                max-height: 340px;
            }

            .fm-copy-panel .fm-card-actions.has-conflict .fm-conflict-seg {
                margin-right: auto;
            }

            .fm-copy-panel .fm-card-actions {
                margin-top: 14px;
            }

            .fm-copy-panel .fm-card-actions .btn:disabled {
                opacity: .5;
            }

            .fm-dest-field {
                display: flex;
                align-items: stretch;
                border: 1px solid var(--fm-line-strong);
                border-radius: 8px;
                overflow: hidden;
                background: var(--fm-surface);
            }

            .fm-dest-field:focus-within {
                border-color: var(--fm-accent);
                box-shadow: var(--fm-focus);
            }

            .fm-dest-prefix {
                display: flex;
                align-items: center;
                padding: 0 10px;
                border-right: 1px solid var(--fm-line);
                background: var(--fm-tier);
                color: var(--fm-muted);
                font-family: var(--fm-mono);
                font-size: 13px;
                white-space: nowrap;
            }

            .fm-dest-field .form-control {
                height: 42px;
                border: 0;
                border-radius: 0;
                font-family: var(--fm-mono);
                font-size: 13.5px;
                box-shadow: none !important;
            }

            .fm-dest-hint {
                margin: 8px 0 0;
                font-size: 13px;
            }

            .fm-dest-hint code {
                padding: 1px 5px;
                border-radius: 4px;
                background: var(--fm-tier);
                color: var(--fm-ink);
                font-size: 12px;
            }

            @media (max-width: 767.98px) {
                .fm-copy-page-grid {
                    grid-template-columns: 1fr;
                }
            }

            /* ---- action icon colours, the same in every place an action appears ---- */
            .fm-topbar .fm-btn i.fa-check-square-o,
            .fm-topbar .fm-btn i.fa-exchange {
                color: var(--fm-ic-select);
            }

            .fm-topbar .fm-btn i.fa-square-o,
            .fm-topbar .fm-search-advanced i,
            .fm-topbar .btn-copy-path i {
                color: var(--fm-ic-neutral);
            }

            .fm-topbar .fm-btn-outline i.fa-plus {
                color: var(--fm-ic-create);
            }

            .fm-topbar .fm-btn i.fa-files-o,
            .btn i.fa-files-o {
                color: var(--fm-ic-copy);
            }

            .fm-topbar .fm-btn i.fa-file-archive-o {
                color: var(--fm-ic-zip);
            }

            .fm-topbar .fm-btn i.fa-archive {
                color: var(--fm-ic-tar);
            }

            .fm-topbar .fm-btn-danger i {
                color: var(--fm-ic-delete);
            }

            .fm-topbar .fm-btn-ghost i.fa-cog {
                color: var(--fm-ic-neutral);
            }

            #main-table .inline-actions > a > i.fa-trash-o,
            #main-table .inline-actions > a > i.fa-trash {
                color: var(--fm-ic-delete);
            }

            #main-table .inline-actions > a > i.fa-pencil-square-o {
                color: var(--fm-ic-edit);
            }

            #main-table .inline-actions > a > i.fa-files-o {
                color: var(--fm-ic-copy);
            }

            #main-table .inline-actions > a > i.fa-link {
                color: var(--fm-ic-link);
            }

            #main-table .inline-actions > a > i.fa-download {
                color: var(--fm-ic-download);
            }

            .dropdown-menu .dropdown-item i.fa-cog,
            .dropdown-menu .dropdown-item i.fa-question-circle {
                color: var(--fm-ic-neutral);
                opacity: 1;
            }

            .dropdown-menu .dropdown-item i.fa-sign-out {
                color: var(--fm-ic-delete);
                opacity: 1;
            }

            .dropdown-menu .dropdown-item i.fa-folder-o {
                color: var(--fm-folder);
            }

            .btn i.fa-cloud-download,
            .btn i.fa-download {
                color: var(--fm-ic-download);
            }

            .btn i.fa-pencil-square,
            .btn i.fa-pencil-square-o,
            .btn i.fa-text-height {
                color: var(--fm-ic-edit);
            }

            .btn i.fa-external-link-square,
            .btn i.fa-link {
                color: var(--fm-ic-link);
            }

            .btn i.fa-file-archive-o {
                color: var(--fm-ic-zip);
            }

            .btn i.fa-database {
                color: var(--fm-ic-select);
            }

            .btn i.fa-check-circle,
            .btn-primary i,
            .btn-success i {
                color: inherit;
            }

            .btn-outline-primary i.fa-check-circle {
                color: var(--fm-ic-download);
            }

            .btn-outline-danger i,
            .btn-outline-primary i.fa-times-circle {
                color: var(--fm-ic-delete);
            }

            .nav-tabs .nav-link i.fa-arrow-circle-o-up {
                color: var(--fm-accent);
            }

            .nav-tabs .nav-link i.fa-link {
                color: var(--fm-ic-link);
            }

            .fm-summary i.fa-folder-o {
                color: var(--fm-folder);
            }

            .fm-summary i.fa-file-o {
                color: var(--fm-ic-copy);
            }

            .fm-summary i.fa-hdd-o {
                color: var(--fm-ic-link);
            }

            @media (max-width: 767.98px) {
                #wrapper {
                    padding-left: 12px;
                    padding-right: 12px;
                }

                #wrapper > .fm-topbar:not(.fixed-top) {
                    margin-left: -12px;
                    margin-right: -12px;
                }

                .card-body {
                    padding: 16px;
                }

            }

            @media (prefers-reduced-motion: reduce) {
                *,
                *::before,
                *::after {
                    transition: none !important;
                    animation-duration: .01ms !important;
                }
            }
        </style>
<?php
}

