            /* ---- Top bar ---- */
            .fm-topbar {
                margin: 0 -12px 1.5rem;
                background: var(--fm-surface);
                color: var(--fm-ink);
                border-bottom: 1px solid var(--fm-line);
                box-shadow: 0 1px 2px rgba(30, 32, 51, .04), 0 6px 16px -10px rgba(30, 32, 51, .18);
                font-size: 14px;
                z-index: 1030;
            }

            .fm-topbar.fixed-top {
                margin: 0;
            }

            body.theme-dark .fm-topbar {
                box-shadow: 0 6px 16px -10px rgba(0, 0, 0, .6);
            }

            body.navbar-fixed {
                margin-top: calc(var(--fm-topbar-h, 112px) + 16px);
            }

            .fm-bar-primary,
            .fm-bar-actions {
                display: flex;
                align-items: center;
                gap: 12px;
                padding: 0 20px;
            }

            .fm-bar-primary {
                min-height: 56px;
            }

            .fm-bar-actions {
                min-height: 50px;
                background: var(--fm-tier);
                border-top: 1px solid var(--fm-line);
                gap: 8px;
            }

            .fm-topbar .fm-brand {
                display: flex;
                align-items: center;
                gap: 10px;
                flex-shrink: 0;
                color: var(--fm-ink);
                font-weight: 600;
                font-size: 15px;
                letter-spacing: -.01em;
            }

            .fm-brand-logo {
                display: block;
                height: 34px;
                width: auto;
            }

            .fm-topbar .fm-brand-name {
                color: var(--fm-muted);
                font-weight: 600;
            }

            /* breadcrumb */
            .fm-crumbs {
                display: flex;
                align-items: center;
                gap: 2px;
                flex: 1 1 0;
                min-width: 0;
                padding-left: 16px;
                border-left: 1px solid var(--fm-line);
                white-space: nowrap;
            }

            .fm-topbar .fm-crumb {
                display: inline-flex;
                align-items: center;
                gap: 6px;
                max-width: 220px;
                padding: 4px 8px;
                border: 0;
                border-radius: 6px;
                background: transparent;
                color: var(--fm-muted);
                overflow: hidden;
                text-overflow: ellipsis;
            }

            .fm-topbar a.fm-crumb:hover,
            .fm-topbar .fm-crumb-more:hover {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            .fm-topbar .fm-crumb.is-current {
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-weight: 600;
            }

            .fm-topbar .fm-crumb-file {
                color: var(--fm-ink);
                font-weight: 500;
            }

            .fm-crumb-sep {
                color: var(--fm-line);
                font-size: 15px;
                padding: 0 1px;
            }

            body.theme-dark .fm-crumb-sep {
                color: var(--fm-muted);
            }

            .fm-topbar .btn-copy-path {
                margin-left: 4px;
                padding: 4px 6px;
                border-radius: 6px;
                color: var(--fm-muted);
                opacity: 1;
            }

            .fm-topbar .btn-copy-path:hover {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            /* server this file manager is running on */
            .fm-server {
                display: inline-flex;
                align-items: center;
                gap: 8px;
                flex: none;
                height: 30px;
                margin: 0 auto;
                padding: 0 14px 0 12px;
                border: 1px solid var(--fm-line);
                border-radius: 999px;
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-size: 13px;
                font-weight: 600;
                white-space: nowrap;
            }

            .fm-server-dot {
                width: 8px;
                height: 8px;
                border-radius: 50%;
                background: var(--fm-success);
                box-shadow: 0 0 0 3px var(--fm-success-soft);
            }

            .fm-server-ip {
                font-family: var(--fm-mono);
                font-variant-numeric: tabular-nums;
                font-weight: 700;
                color: var(--fm-ink);
            }

            /* search */
            .fm-search {
                position: relative;
                display: flex;
                align-items: center;
                flex: 0 1 340px;
                min-width: 200px;
                height: 36px;
                border: 1px solid var(--fm-line);
                border-radius: 8px;
                background: var(--fm-tier);
                transition: border-color .15s, box-shadow .15s, background .15s;
            }

            .fm-search:focus-within {
                border-color: var(--fm-accent);
                background: var(--fm-surface);
                box-shadow: var(--fm-focus);
            }

            .fm-search > .fa-search {
                position: absolute;
                left: 11px;
                color: var(--fm-muted);
                pointer-events: none;
            }

            .fm-topbar #search-addon {
                flex: 1;
                min-width: 0;
                height: 100%;
                padding: 0 8px 0 33px;
                border: 0;
                background: transparent;
                color: var(--fm-ink);
                font-size: 14px;
                outline: none;
            }

            .fm-topbar #search-addon::placeholder {
                color: var(--fm-muted);
            }

            .fm-topbar .fm-search-advanced {
                display: inline-flex;
                align-items: center;
                gap: 6px;
                height: 26px;
                margin-right: 4px;
                padding: 0 8px;
                border-radius: 5px;
                color: var(--fm-muted);
                font-size: 13px;
                white-space: nowrap;
            }

            .fm-topbar .fm-search-advanced:hover {
                background: var(--fm-hover);
                color: var(--fm-ink);
            }

            /* account */
            .fm-account-toggle {
                display: flex;
                align-items: center;
                gap: 8px;
                padding: 4px 8px 4px 4px;
                border: 1px solid transparent;
                border-radius: 999px;
                background: transparent;
                color: var(--fm-ink);
            }

            .fm-account-toggle:hover,
            .fm-account-toggle[aria-expanded="true"] {
                border-color: var(--fm-line);
                background: var(--fm-hover);
            }

            .fm-avatar {
                display: grid;
                place-items: center;
                width: 28px;
                height: 28px;
                border-radius: 50%;
                background: var(--fm-accent-soft);
                color: var(--fm-accent);
                font-weight: 700;
                font-size: 13px;
            }

            .fm-account-name {
                font-weight: 500;
                max-width: 140px;
                overflow: hidden;
                text-overflow: ellipsis;
            }

            .fm-topbar .dropdown-menu {
                font-size: 14px;
                border-radius: 8px;
                padding: 6px;
            }

            .fm-topbar .dropdown-item {
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 7px 10px;
                border-radius: 5px;
            }

            .fm-topbar .dropdown-item i {
                width: 16px;
                text-align: center;
                opacity: .7;
            }

            /* buttons */
            .fm-group {
                display: flex;
                align-items: center;
                gap: 4px;
                flex-shrink: 0;
            }

            .fm-topbar .fm-btn {
                display: inline-flex;
                align-items: center;
                gap: 7px;
                height: 32px;
                padding: 0 12px;
                border: 1px solid transparent;
                border-radius: 7px;
                background: transparent;
                color: var(--fm-ink);
                font-size: 13.5px;
                font-weight: 500;
                line-height: 1;
                white-space: nowrap;
                cursor: pointer;
                transition: background .15s, border-color .15s, color .15s;
            }

            .fm-topbar .fm-btn i {
                font-size: 14px;
                color: var(--fm-muted);
            }

            .fm-topbar .fm-btn-ghost:hover:not(:disabled) {
                background: var(--fm-hover);
            }

            .fm-topbar .fm-btn-primary {
                background: var(--fm-accent);
                color: var(--fm-accent-ink);
            }

            .fm-topbar .fm-btn-primary i {
                color: inherit;
            }

            .fm-topbar .fm-btn-primary:hover {
                filter: brightness(1.12);
                color: var(--fm-accent-ink);
            }

            .fm-topbar .fm-btn-outline {
                border-color: var(--fm-line);
                background: var(--fm-surface);
            }

            .fm-topbar .fm-btn-outline:hover {
                border-color: var(--fm-accent);
                color: var(--fm-accent);
            }

            .fm-topbar .fm-btn-danger {
                color: var(--fm-danger);
            }

            .fm-topbar .fm-btn-danger i {
                color: inherit;
            }

            .fm-topbar .fm-btn-danger:hover:not(:disabled) {
                background: var(--fm-danger-soft);
            }

            .fm-topbar .fm-btn:disabled {
                opacity: .42;
                cursor: not-allowed;
            }

            /* "Preparing download…" stays fully visible while the zip is built */
            .fm-topbar .fm-btn.is-busy:disabled {
                opacity: 1;
                cursor: progress;
            }

            .fm-topbar .fm-btn:focus-visible,
            .fm-topbar .fm-crumb:focus-visible,
            .fm-topbar .btn-copy-path:focus-visible,
            .fm-topbar .fm-search-advanced:focus-visible,
            .fm-account-toggle:focus-visible,
            .fm-topbar .fm-brand:focus-visible {
                outline: none;
                box-shadow: var(--fm-focus);
            }

            .fm-divider {
                width: 1px;
                height: 22px;
                margin: 0 6px;
                background: var(--fm-line);
                flex-shrink: 0;
            }

            /* selection: quiet until something is ticked */
            .fm-selection {
                display: flex;
                align-items: center;
                gap: 2px;
                margin-left: auto;
                padding: 3px 3px 3px 12px;
                border: 1px solid transparent;
                border-radius: 9px;
                flex-shrink: 0;
                transition: background .2s, border-color .2s;
            }

            .fm-selection-count {
                margin-right: 6px;
                color: var(--fm-muted);
                font-size: 13px;
                font-variant-numeric: tabular-nums;
            }

            .fm-selection.has-selection {
                background: var(--fm-accent-soft);
                border-color: color-mix(in srgb, var(--fm-accent) 25%, transparent);
            }

            .fm-selection.has-selection .fm-selection-count {
                color: var(--fm-accent);
                font-weight: 600;
            }

            .fm-selection.has-selection .fm-btn-ghost:hover {
                background: var(--fm-surface);
            }

            .fm-selection .fm-divider {
                margin: 0 4px;
            }

            /* narrower screens */
            @media (max-width: 1199.98px) {
                .fm-search-advanced span,
                .fm-account-name {
                    display: none;
                }
            }

            @media (max-width: 991.98px) {
                .fm-bar-primary {
                    flex-wrap: wrap;
                    row-gap: 0;
                    padding: 0 12px;
                }

                .fm-bar-primary > .fm-brand {
                    min-height: 52px;
                }

                .fm-search {
                    flex: 1 1 160px;
                    order: 2;
                }

                .fm-server {
                    order: 2;
                    margin: 0;
                }

                .fm-bar-primary > .fm-group,
                .fm-account,
                .fm-bar-primary > .fm-btn {
                    order: 3;
                }

                .fm-crumbs {
                    order: 4;
